INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (110, 14, 18, 'Introducción al HVAC: Confort Humano y Principios Básicos', 'En esta primera lección aprenderás que el verdadero objetivo del técnico en HVAC no es instalar máquinas, sino proveer confort humano. El instructor explica cómo los sistemas de aire acondicionado trabajan removiendo calor, no “enfriando”, y presenta los principales equipos utilizados en la industria: sistemas split, sistemas de paquete y mini splits. También se introducen los conceptos de indoor coil, outdoor coil y su función como intercambiadores de calor.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1113390498?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Introducción al HVAC: Confort Humano y Principios Básicos\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 11, 41, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (113, 14, 18, 'El Calor y la Temperatura: Fundamentos Esenciales del HVAC', 'En esta lección aprenderás qué es el calor, cómo se mueve entre sustancias y por qué el frío no existe como fenómeno físico, sino que es la ausencia de calor. El instructor explica las diferencias entre calor y temperatura, introduce el concepto de cero absoluto y presenta las escalas más utilizadas (Celsius, Fahrenheit, Kelvin y Rankine). Además, conocerás los instrumentos básicos para medir la temperatura y la humedad en el aire: bulbo seco, bulbo mojado y psicrómetro.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1114059273?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"El Calor y la Temperatura: Fundamentos Esenciales del HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 33, 46, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (114, 14, 18, 'Relación entre Temperatura, Presión y Conversiones en HVAC', 'En esta lección aprenderás cómo se relacionan la temperatura, la presión y la humedad relativa en los sistemas HVAC. El instructor explica el uso del psicrómetro y el higrómetro, describe el papel de los gases inertes en la presión de los sistemas, y enseña a realizar conversiones entre escalas Celsius y Fahrenheit con ejemplos prácticos. Esta lección sienta las bases para entender cómo los técnicos pueden interpretar mediciones en campo y aplicar los cálculos correctos.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1114089349?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Relación entre Temperatura, Presión y Conversiones en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 20, 27, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (115, 14, 18, 'La Primera Ley de la Termodinámica y la Unidad BTU', 'En esta lección aprenderás los tres métodos principales de transferencia de calor: conducción, convección y radiación. El instructor explica con ejemplos prácticos cómo se mueve el calor en los materiales y en los espacios. Además, se introduce la importancia de los cálculos de carga térmica para seleccionar equipos correctamente, incluyendo la referencia a los manuales J, D y S utilizados en la industria.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1115288214?badge=0&autopause=0&player_id=0&app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Transferencia de Calor y Cálculos de Carga en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 16, 18, 0, 4, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (116, 14, 18, 'Transferencia de Calor y Cálculos de Carga en HVAC', 'En esta lección aprenderás los tres métodos principales de transferencia de calor: conducción, convección y radiación. El instructor explica con ejemplos prácticos cómo se mueve el calor en los materiales y en los espacios. Además, se introduce la importancia de los cálculos de carga térmica para seleccionar equipos correctamente, incluyendo la referencia a los manuales J, D y S utilizados en la industria.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1115323016?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Transferencia de Calor y Cálculos de Carga en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 34, 3, 0, 5, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (118, 14, 25, 'Fundamentos de la transferencia de calor', 'En esta primera lección, aprenderás los principios básicos de cómo se transfiere la energía térmica en los sistemas de HVAC. El instructor explica los tres mecanismos principales —conducción, convección y radiación— con ejemplos cotidianos que te permitirán comprender cómo viaja el calor a través de distintos medios. Estos conceptos son esenciales para entender más adelante cómo se diseña, instala y diagnostica un sistema de climatización.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1115888032?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Fundamentos de la transferencia de calor\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 32, 27, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (119, 14, 25, 'Calor sensible y calor latente en HVAC', 'En esta lección aprenderás a diferenciar dos tipos de calor fundamentales en los sistemas de climatización: el calor sensible, que se puede medir y sentir, y el calor latente, relacionado con los cambios de estado de la materia. El instructor explica cómo medir cada uno, qué instrumentos usar (bulbo seco y bulbo mojado), y cuándo aplicarlos en calefacción y en aire acondicionado. Esta base conceptual es clave para comprender la humedad, la comodidad térmica y los cálculos posteriores de carga térmica.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1115338426?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Calor sensible y calor latente en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 21, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (120, 14, 25, 'Delta T y la fórmula sensible en HVAC', 'En esta lección se introduce el concepto de Delta T (ΔT) como indicador del desempeño de un sistema HVAC. Aprenderás cómo calcular la diferencia de temperatura entre retorno y suministro, y cómo se relaciona con el flujo de aire (CFM) para estimar la energía transferida en BTU/h mediante la fórmula sensible:
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (121, 16, 19, 'Introducción y materiales de estudio para la A2L', 'En esta lección se presenta el curso de refrigerantes A2L, destacando la importancia de estudiar con materiales oficiales y actualizados. El instructor explica el uso del libro guía en PDF y físico, así como la necesidad de certificaciones adicionales para manejar estos nuevos refrigerantes. También se introduce el concepto del Core, que incluye seguridad, transporte, equipo de protección personal y consideraciones medioambientales, como base para comprender los riesgos y procedimientos al trabajar con refrigerantes A2L.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1119655225?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Introducción y materiales de estudio para la A2L\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 26, 28, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (122, 14, 25, 'Flujo de Aire y Presión Estática', 'En esta lección verás cómo el flujo de aire (CFM) y la presión estática (SP) determinan la capacidad real de un sistema HVAC. Aprenderás qué es el TESP (Total External Static Pressure), cómo medirlo con manómetro (in. w.c.), y cómo usar la tabla del blower para estimar el CFM real según la velocidad seleccionada. También identificarás las pérdidas de carga más comunes (filtros, serpentín/coil, codos, ducto flexible) y cómo corregirlas para recuperar desempeño y confort.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121310999?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Flujo de Aire y Presión estática\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 28, 39, 0, 4, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (123, 11, 20, 'Introducción y Seguridad en el Diagnóstico de Motores', 'En esta primera lección, el instructor introduce la Unidad 20 sobre diagnóstico de motores eléctricos, explicando los objetivos principales del tema y los diferentes tipos de motores que el técnico debe reconocer en el campo. Además, se abordan las precauciones de seguridad fundamentales, como el uso de bloqueos eléctricos, la descarga correcta de capacitores y las prácticas seguras al manipular compresores y ejes. Esta base es esencial para iniciar el diagnóstico profesional y seguro de motores eléctricos.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121334722?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Introducción y Seguridad en el Diagnóstico de Motores\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 5, 29, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (124, 11, 20, 'Problemas Eléctricos y Mecánicos en Motores', 'En esta segunda lección, el instructor explica cómo diferenciar entre fallas eléctricas y fallas mecánicas en motores eléctricos. Se presentan ejemplos reales en compresores herméticos y semiherméticos, además de anécdotas en plantas procesadoras donde se manejan motores de gran capacidad. El enfoque está en diagnosticar correctamente para evitar reemplazos innecesarios, optimizar costos y llenar reportes técnicos que respalden el trabajo del técnico.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121373938?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Problemas Eléctricos y Mecánicos en Motores\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 23, 55, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (125, 11, 20, 'Ensamble, Poleas, Bandas y Diagnóstico Avanzado', 'En esta lección se aborda la parte práctica del desmontaje de un drive assembly, los problemas más comunes relacionados con valeros, poleas y bandas, y cómo afectan al desempeño del motor. El instructor explica el uso de herramientas especializadas, calibradores de tensión y métodos de alineación. Además, se revisan problemas eléctricos típicos como embobinados abiertos, cortos y fallas a tierra, mostrando cómo diagnosticarlos correctamente con instrumentación.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121375659?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Ensamble, Poleas, Bandas y Diagnóstico Avanzado\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 37, 54, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (126, 11, 21, 'Diagnóstico de embobinados abiertos en motores eléctricos', 'En esta lección aprenderás cómo identificar un embobinado abierto (open winding) en motores monofásicos utilizando un multímetro. Se revisan las lecturas típicas de resistencia entre común, run y start, y se muestran ejemplos prácticos de diagnóstico. Además, se explican casos de fallas reales, cómo diferenciar un bobinado bueno de uno abierto, y qué hacer en caso de encontrar un protector térmico (overload) activado.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121388136?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Diagnóstico de embobinados abiertos en motores eléctricos\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 17, 4, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (127, 11, 21, 'Motores PSC y conexiones a 240V', 'En esta lección se estudia el funcionamiento de los motores PSC (Permanent Split Capacitor) y su aplicación en sistemas HVAC. Se explican las conexiones de alimentación a 240V, el papel del capacitor de marcha (Run Capacitor) y la identificación práctica de los terminales común, run y start mediante mediciones de resistencia. El instructor también muestra ejemplos con compresores reales, destacando la importancia de reconocer cables y asegurar una correcta instalación.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121390296?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Motores PSC y conexiones a 240V\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 18, 40, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (128, 11, 21, 'Diagnóstico de compresores y fallas por cortocircuito', 'En esta lección se realizan pruebas prácticas en compresores reales para identificar terminales, verificar continuidad de los embobinados y diagnosticar problemas. Además, se estudia el funcionamiento del protector térmico (overload protector), el calentador de cárter (crankcase heater) y el papel de los contactores en la alimentación del motor. Finalmente, se aborda un tema crítico: los cortocircuitos en embobinados, sus causas más comunes (humedad, ácido, deterioro del esmalte) y los procedimientos adecuados para limpiar y proteger el sistema después de una falla de este tipo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121390666?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Diagnóstico de compresores y fallas por cortocircuito\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 2, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (129, 11, 22, 'Resistencias y diagnóstico básico de motores monofásicos', 'En esta lección aprenderás cómo se mide la resistencia en los embobinados de un motor eléctrico monofásico, la diferencia entre los devanados de arranque (start) y de trabajo (run), y cómo identificar problemas comunes como cortos internos o caída de resistencia. También se introducen conceptos fundamentales de amperaje y el inicio del estudio de la impedancia en los motores.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121390150?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Resistencias y diagnóstico básico de motores monofásicos\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 22, 35, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (130, 11, 22, 'Fallas comunes en embobinados y motores trifásicos', 'En esta lección se estudian las fallas más frecuentes en los embobinados: cortos internos, motores aterrizados a tierra y problemas en motores trifásicos. También se explica el uso del megóhmetro para diagnósticos avanzados y se presenta un ejemplo de llamada de servicio real en un supermercado, donde el aire acondicionado falla por congelamiento del evaporador debido a un blower motor dañado.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121391668?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Fallas comunes en embobinados y motores trifásicos\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 33, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (131, 11, 22, 'Diagnóstico y sustitución de blower motor en campo', 'En esta lección se revisan los pasos prácticos para diagnosticar fallas en un blower motor de aire acondicionado: chequeo de voltaje, conexiones, capacitor y resistencias. También se explica cómo identificar un embobinado abierto, cuándo reemplazar un motor y el procedimiento correcto para desmontarlo y montarlo. Finalmente, se estudia cómo verificar el flujo de aire y la diferencia de temperatura (delta T y temperature rise) para asegurar un trabajo exitoso en campo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121391851?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Diagnóstico y sustitución de blower motor en campo\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 16, 34, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (132, 11, 23, 'Preparación para el Certificado NATE: Registro y Primer Examen', 'En esta lección aprenderás cómo prepararte para obtener tu certificación NATE, comenzando por el uso de materiales oficiales de estudio y guías prácticas. Además, el instructor explica paso a paso cómo crear tu cuenta en la página oficial, completar el registro, realizar el pago y acceder al examen Ready to Work. Una clase fundamental para iniciar tu camino hacia la certificación técnica en HVAC.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121656539?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Preparación para el Certificado NATE: Registro y Primer Examen\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 29, 10, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (133, 17, 24, 'Repaso general y preparación para exámenes en HVAC', 'En esta lección, el instructor repasa los principales conceptos vistos anteriormente: electricidad, transferencia de calor, motores, herramientas, tubería y soldadura. Además, explica la importancia de repasar constantemente porque estos temas son la base de los exámenes de certificación (ESCO, NATE). El estudiante comprenderá qué áreas reforzar y cómo organizar su estudio antes de enfrentar los exámenes.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121662446?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Repaso general y preparación para exámenes en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 13, 23, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (134, 17, 24, 'Introducción a la detección de fugas en sistemas HVAC', 'En esta lección, el instructor introduce el proceso de detección de fugas, un paso fundamental después de realizar brazing en tuberías. Se explican los procedimientos previos a la carga de refrigerante: brazing, pruebas de fuga, vacío y finalmente la carga. Además, se abordan los efectos de la vibración en las instalaciones y la importancia de los componentes antivibración para evitar fallas y fugas.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121664702?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Introducción a la detección de fugas en sistemas HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 20, 13, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (135, 17, 24, 'Tipos de fugas y métodos de prueba en sistemas HVAC', 'En esta lección se estudian los diferentes tipos de fugas que pueden presentarse en los sistemas de refrigeración y aire acondicionado. El instructor explica cómo realizar pruebas de presión con nitrógeno y refrigerante, la influencia de las imperfecciones de fábrica, y la importancia de entender la relación entre presión y temperatura. También se presentan ejemplos reales de fallas en condensadores y evaporadores, resaltando cómo identificar fugas difíciles y cómo manejar situaciones relacionadas con garantías y clientes.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121664945?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Tipos de fugas y métodos de prueba en sistemas HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 34, 52, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (136, 17, 24, 'Procedimientos avanzados de detección de fugas en HVAC', 'En esta lección se profundiza en los procedimientos avanzados de prueba para detectar fugas en sistemas HVAC. El instructor explica cómo manejar sistemas pequeños y grandes, el uso de válvulas solenoides, las limitaciones de presión en evaporadores y compresores, así como el uso de herramientas como el microfoam y los detectores electrónicos. Además, se abordan lineamientos legales del EPA para evitar sanciones, y se concluye con recomendaciones prácticas para la preparación en pruebas reales.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121665134?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Procedimientos avanzados de detección de fugas en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 15, 43, 0, 4, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (137, 14, 25, 'PSI, Columna de Agua y Vacío', 'En esta lección se ordenan las unidades y formas de medir presión usadas en HVAC: PSI (psig/psia), pulgadas de columna de agua (in. w.c.) y vacío en inHg y micrones. Verás qué representa cada unidad, cuándo se usa (refrigeración vs. aire/ductos), cómo se interpretan los manómetros (gauges) y por qué el cero en el gauge corresponde a la presión atmosférica. También se explica la relación con el barómetro (≈29.92 inHg a nivel del mar) y la importancia del buen sellado y la lectura correcta del vacío para asegurar la calidad del trabajo en campo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121692086?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"PSI, Columna de Agua y Vacío\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 37, 37, 0, 5, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (138, 14, 25, 'Aplicaciones Prácticas de Medición', 'En esta última lección, el instructor aplica los conceptos vistos previamente (ΔT, flujo de aire, presión estática, PSI, vacío) a ejemplos reales de diagnóstico en sistemas HVAC. Se muestran casos prácticos de cómo usar termómetros, manómetros, medidores de micrones y manómetros de columna de agua para identificar problemas de rendimiento. El enfoque es llevar la teoría a la práctica, mostrando cómo las mediciones permiten tomar decisiones correctas en campo. Esta lección es un llamado a la responsabilidad profesional del técnico HVAC.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121693183?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Aplicaciones Prácticas de Medición\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 34, 53, 0, 6, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (143, 17, 27, 'Certificaciones y fundamentos del EPA en HVAC', 'En esta primera lección se explica la importancia del cumplimiento con el EPA (Agencia de Protección Ambiental de EE.UU.) en el área de HVAC, ilustrado con un caso real de sanción por fugas de refrigerante. Además, se detallan los distintos exámenes y certificaciones que todo técnico debe completar (OSHA, Ready to Work, Core NAIT y EPA), junto con los tipos de certificaciones del EPA (Tipo 1, 2 y 3). Finalmente, se introduce el concepto de Standing Pressure, que será clave en las pruebas de fugas.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121739801?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Certificaciones y fundamentos del EPA en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 16, 20, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (144, 17, 27, 'Pruebas de fugas: Standing Pressure y Trace Gas', 'En esta lección aprenderás el procedimiento para realizar pruebas de fugas en sistemas HVAC utilizando la técnica de Standing Pressure. Se explica cómo usar nitrógeno y gas trazador (Trace Gas) de manera correcta y segura, respetando las regulaciones del EPA. También se abordan conceptos clave como el vacío de 500 micrones, la ecualización de presiones y el uso de detectores electrónicos. Esta sección es esencial para dominar la detección profesional de fugas en equipos de refrigeración y aire acondicionado.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121741647?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Pruebas de fugas: Standing Pressure y Trace Gas\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 23, 37, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (145, 17, 27, 'Pruebas de presión y detección avanzada de fugas', 'En esta lección se estudian las presiones de prueba aplicables a distintos tipos de sistemas HVAC (Tipo 1, 2 y 3), con énfasis en chillers de baja presión y el funcionamiento del rupture disc. Además, se profundiza en los detectores electrónicos modernos y en la importancia de utilizar equipos certificados y a prueba de explosión para los nuevos refrigerantes inflamables. Finalmente, se revisa la metodología de Standing Pressure prolongado, clave para detectar fugas pequeñas en sistemas grandes.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1121741740?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Pruebas de presión y detección avanzada de fugas\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 30, 27, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (146, 14, 28, 'Introducción, seguridad y ruta de certificación', 'El instructor abre con un repaso breve del módulo anterior y establece la importancia del enfoque práctico del curso. Destaca que el aprendizaje no es solo teórico, sino orientado al trabajo real en campo.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (147, 14, 28, 'Refrigerantes, ambiente y transición R22/R410A', 'En esta lección el instructor profundiza en el impacto ambiental y económico de los refrigerantes.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (148, 14, 28, 'Repaso técnico I: calor, temperatura, BTU y termodinámica', 'En este bloque el instructor repasa las bases físicas y matemáticas esenciales para entender los sistemas de refrigeración.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (149, 14, 28, 'Repaso técnico II: calor sensible/latente y fórmula 1.08', 'En esta lección se introduce la diferencia entre calor sensible y latente, conceptos básicos para el análisis de confort y climatización:
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (150, 14, 28, 'Presión y vacío: medición e instrumentos (PSI, inHg, micrones)', 'El instructor introduce la presión como fuerza por unidad de área (PSI) y conecta la presión atmosférica con su lectura en pulgadas de mercurio (inHg). Explica la diferencia entre presión absoluta (psia) y presión manométrica (psig), y cómo interpretarlas en la práctica HVAC. Aborda el vacío operativo en micrones, objetivos de deshidratación del sistema y la prueba de estabilidad (rise test). Finalmente, describe el funcionamiento de los manómetros (tubo de Bourdon), barómetro y los compound gauges que combinan vacío/presión.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122036961?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Presión y vacío: medición e instrumentos (PSI, inHg, micrones)\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 15, 13, 0, 5, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (151, 13, 29, 'Introducción a BACnet y control por zonas en calefacción', 'En esta lección aprenderás qué es el sistema BACnet y cómo se utiliza en edificios para controlar equipos de aire acondicionado y calefacción de manera automatizada. Revisaremos cómo se distribuye el aire en diferentes zonas a través de cajas BAV, la importancia de los termostatos por área, y cómo se combinan el aire acondicionado y la calefacción en sistemas centralizados. Finalmente, se explicará la eficiencia de los equipos (80% y 90%) y el papel del flue pipe en la pérdida de calor.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122097847?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Introducción a BACnet y control por zonas en calefacción\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 18, 10, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (152, 13, 29, 'Ignición, etapas de calefacción y controles electrónicos', 'En esta lección se estudian los distintos métodos de ignición en los equipos de calefacción, desde chispa hasta piloto intermitente. Se explica cómo identificar si un equipo es de una o dos etapas mediante sensores y tarjetas electrónicas, y se describen los tipos de controles y placas de circuito más comunes en la industria. Finalmente, se enfatiza la importancia de recopilar información completa del equipo y de medir correctamente la presión de gas y la electricidad, resaltando que “si no mides, estás adivinando”.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122101480?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Ignición, etapas de calefacción y controles electrónicos\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 15, 4, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (153, 13, 29, 'Medición de gas y cálculo de BTUs en equipos de calefacción', 'En esta lección aprenderás a medir correctamente el gas en un equipo de calefacción, diferenciando entre presión de entrada (inlet) y de salida. Se revisa cómo calcular el input y el output de BTUs utilizando el medidor de gas (clock meter) y se estudian los conceptos de under fire y over fire. Además, se explican los efectos de la eficiencia en la capacidad real de calefacción y cómo los sensores de flama rectifican la combustión. Finalmente, se prepara el terreno para la práctica en campo con el procedimiento de medición.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122101617?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Medición de gas y cálculo de BTUs en equipos de calefacción\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 26, 59, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (154, 13, 30, 'Uso del Dual Port Manometer y Medición de Presión de Gas', 'En esta lección aprenderás el uso práctico del dual port manometer, una herramienta esencial para técnicos en calefacción. Mario explica sus funciones, cómo conectar el kit de mangueras y adaptadores, y cómo medir la presión de gas de entrada y salida en la válvula. También se revisan procedimientos de seguridad como la calibración en cero y la pre-purga del sistema antes de la combustión.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122101302?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Uso del Dual Port Manometer y Medición de Presión de Gas\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 15, 21, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (155, 13, 30, 'Cálculo de BTUs y Ajuste del Input de Gas', 'En esta lección aprenderás cómo calcular el rendimiento real de un sistema de calefacción midiendo la presión de gas, el temperature rise y el flujo de aire. Mario explica cómo relacionar estos datos para obtener los BTUs de salida, evaluar la eficiencia del equipo y realizar ajustes de gas en la válvula. Finalmente, se muestra cómo confirmar el input de gas usando el medidor del suministro.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122101693?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Cálculo de BTUs y Ajuste del Input de Gas\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 14, 45, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (156, 14, 28, 'Materia, Masa, Peso, Volumen y Estados', 'El instructor inicia Unidad 2 definiendo materia (ocupa espacio y tiene masa) y su relación con peso y volumen. Revisa los estados de la materia (sólido, líquido, gas) y cómo calor y presión provocan cambios de estado y alteran el comportamiento (forma, volumen, presión). Introduce prácticas de seguridad con cilindros presurizados (uso obligatorio de regulador y válvula de alivio). Cierra con densidad y la noción de gravedad específica referida al agua (62.4 lb/ft³), resolviendo un ejemplo numérico. Se deja listo el terreno para la próxima lección: volumen específico.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122274601?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Materia, Masa, Peso, Volumen y Estados\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 27, 47, 0, 6, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (157, 14, 28, 'Volumen específico y densidad del aire', 'El instructor explica el volumen específico del aire como la cantidad de volumen que ocupa una libra de gas. A condiciones estándar, 1 lb de aire ocupa 13.33 ft³, lo que corresponde a una densidad de 0.075 lb/ft³.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (158, 14, 28, 'Aplicaciones: flujo de aire y compresores (succión vs descarga)', 'Esta lección conecta conceptos teóricos de volumen específico y densidad con la operación real de equipos HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (159, 14, 28, 'Gráficas P-v-ρ y gravedad específica de gases', 'El instructor utiliza las figuras del libro (2.7, 2.8, 2.9, pág. 33) para explicar gráficamente la relación entre presión, volumen y densidad.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (160, 14, 28, 'Ley de los Gases I: psig/psia, escalas absolutas y Ley de Boyle (con tanques)', 'El instructor aterriza la Ley de los Gases a operación real de HVAC: diferencia entre psig y psia y la necesidad de escalas absolutas (Rankine/Kelvin) al aplicar ecuaciones. Presenta la Ley de Boyle (relación inversa entre volumen y presión absoluta a temperatura constante) y la contextualiza con tanques de refrigerante (virgen/recobrado) y el pistón del compresor (página 33), mostrando cómo cambian P y V sin variar T. Cierra anunciando que las otras leyes se verán en la próxima clase.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122060694?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Ley de los Gases I: psig/psia, escalas absolutas y Ley de Boyle (con tanques)\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 52, 0, 10, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (161, 14, 31, 'Ley de Boyle: demostración, unidades y ejemplo guiado', 'La lección introduce la Ley de Boyle (relación inversa entre presión y volumen a temperatura constante). Se trabaja con unidades absolutas (PSIA) y se enfatiza la diferencia con PSIG. Se realiza una demostración conceptual tipo “émbolo/pistón” y un ejemplo numérico paso a paso, con cuidados sobre cifras significativas.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122366544?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Ley de Boyle: demostración, unidades y ejemplo guiado\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 14, 4, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (162, 14, 31, 'Ley de Charles + implicaciones en HVAC (flujo de aire, control)', 'Se presenta la Ley de Charles (a presión constante, el volumen de un gas es proporcional a su temperatura absoluta). Se conectan implicaciones prácticas en HVAC: flujo de aire, motores (PSC/ECM), control por termostato y el efecto de T en la expansión del aire en conductos.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122367866?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Ley de Charles + implicaciones en HVAC (flujo de aire, control)\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 27, 52, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (163, 14, 31, 'Ley de Charles en números: Rankine/Kelvin y ejercicios guiados', 'Se profundiza en cálculo con la Ley de Charles utilizando Rankine/Kelvin, con ejercicios resueltos. Se refuerza la conversión a temperatura absoluta, el uso correcto de unidades, y el control de cifras significativas.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122368253?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Ley de Charles en números: Rankine/Kelvin y ejercicios guiados\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 23, 18, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (164, 14, 31, 'Relación Presión–Temperatura (volumen constante): caso de tanque estacional', 'Se introduce la relación Presión–Temperatura a volumen constante (forma práctica de Gay‑Lussac), aplicada a un tanque que experimenta variaciones estacionales. Se trabaja lectura de tablas y el concepto de comportamiento a volumen fijo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122368273?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Relación Presión–Temperatura (volumen constante): caso de tanque estacional\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 18, 22, 0, 4, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (165, 14, 31, 'Aplicación con refrigerantes: R‑410A y verificación en campo', 'Aterrizamos la relación P–T en un caso real con R‑410A: cómo leer tablas P–T de saturación, contrastarlas con la temperatura del cilindro/sistema, y realizar verificaciones rápidas de coherencia en campo (PSIG vs PSIA, temperatura ambiente/solarización del cilindro, seguridad). Se introduce el vínculo con sobrecalentamiento y subenfriamiento a nivel conceptual.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122384176?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Aplicación con refrigerantes: R‑410A y verificación en campo\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 19, 31, 0, 5, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (166, 14, 31, 'Ley combinada de los gases: fundamento, derivación y ejemplo aplicado', 'Se presenta la Ley combinada P1V1/T1 = P2V2/T2, integrando Boyle, Charles y Gay‑Lussac. Se usa cuando P, V y T cambian simultáneamente. Incluye un ejemplo de cálculo completo y verificación del sentido físico del resultado.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122385082?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Ley combinada de los gases: fundamento, derivación y ejemplo aplicado\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 17, 0, 0, 6, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (167, 14, 31, 'Práctica guiada con manómetros: resolución paso a paso', 'Práctica hands‑on con manifold (analógico/digital): montaje, purga, orden correcto de conexiones, lectura de alta/baja, registro de datos y resolución guiada de un caso de servicio. Se trabaja seguridad, procedimiento y interpretación.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122385100?badge=0&autopause=0&player_id=0&app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Práctica guiada con manómetros: resolución paso a paso (Parte 1)\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 32, 58, 0, 7, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (168, 13, 32, 'Medición de consumo de gas y cálculo de BTUs', 'En esta lección aprenderás a medir el consumo de gas en una caldera y cómo convertir esos datos en BTUs. El instructor guía paso a paso la toma de mediciones, el cálculo de promedios y el ajuste de tiempos para obtener el valor correcto de entrada (input) y salida (output) en BTUs. Al final, la máquina queda calibrada con un resultado real cercano a 80,124 BTUs.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122545908?badge=0&autopause=0&player_id=0&app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Medición de consumo de gas y cálculo de BTUs\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 17, 8, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (169, 13, 32, 'Cálculo de eficiencia mediante Temperature Rise', 'En esta lección aprenderás a relacionar el caudal de aire (CFM), la diferencia de temperatura entre retorno y suministro (temperature rise) y el factor 1.08, para calcular la eficiencia real de la máquina. Se explica cómo interpretar los valores obtenidos, los rangos adecuados para un buen desempeño y la importancia de medir correctamente para evitar cálculos erróneos.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122546196?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Cálculo de eficiencia mediante Temperature Rise\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 12, 10, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (170, 13, 32, 'Identificación de equipos y medición de presiones en calefacción', 'En esta lección aprenderás a identificar una unidad de alta eficiencia (95% categoría 4), medir la presión de gas en la entrada y salida (inlet y outlet), interpretar fallas comunes de encendido y comprender la lectura en columna de agua (WC, Water Column). Además, se muestra cómo diagnosticar bloqueos de arranque, códigos de error y la importancia de no hacer bypass a los sistemas de seguridad.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122547069?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Identificación de equipos y medición de presiones en calefacción\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 13, 23, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (171, 13, 33, 'Conexión de termostato y zonas en sistemas de calefacción', 'En esta lección aprenderás cómo realizar las conexiones de un termostato en un sistema de calefacción, identificando los cables más comunes (R, C, W, Y, G), su función y la forma correcta de instalarlos. También se revisa el uso de adaptadores, la conexión al equipo (equipment), y la importancia de la presión estática en sistemas con múltiples zonas y dampers. El objetivo es que entiendas cómo garantizar un funcionamiento seguro y eficiente de un sistema de climatización.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122546170?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Conexión de termostato y zonas en sistemas de calefacción\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 12, 35, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (172, 13, 34, 'Certificaciones y especialización en calefacción', 'En esta primera lección, el instructor explica la relevancia de contar con certificaciones reconocidas en la industria HVAC y cómo éstas impactan en las oportunidades laborales. También se analiza la diferencia entre escuelas que ofrecen formación incompleta (solo EPA) y aquellas que preparan a los estudiantes con especialidades. Finalmente, se introduce el tema de la calefacción, destacando su importancia dentro de la formación técnica y repasando los principales tipos de combustibles.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122576007?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Certificaciones y especialización en calefacción\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 14, 40, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (173, 13, 34, 'Combustibles, conversiones y presiones en calefacción', 'En esta lección, el instructor explica en detalle los diferentes combustibles utilizados en calefacción y cómo se aplican según la región y el tipo de equipo. Se estudia la conversión de equipos de gas natural a propano, destacando las precauciones de seguridad y los cambios necesarios en las espreas y válvulas. Además, se revisan las presiones estándar de operación en el manifold y cómo ajustarlas correctamente para garantizar un funcionamiento seguro y eficiente de los sistemas.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122576114?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Combustibles, conversiones y presiones en calefacción\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 30, 11, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (174, 13, 34, 'Combustión, manómetros y seguridad en calefacción', 'En esta lección, el instructor profundiza en los fundamentos de la combustión en sistemas de calefacción, los instrumentos de medición utilizados y los riesgos asociados a una mala mezcla de aire y gas. Se revisan los subproductos de la combustión adecuada y los efectos peligrosos cuando el proceso es deficiente. También se presentan ejemplos prácticos de fallas en instalaciones y se comparan equipos de 80% y 90% de eficiencia. Finalmente, se muestra cómo se usan válvulas de laboratorio para simular problemas y entrenar a los técnicos.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122576151?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Combustión, manómetros y seguridad en calefacción\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 23, 49, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (175, 13, 35, 'Fundamentos de combustión y análisis de flama', 'En esta lección aprenderás los principios básicos de la combustión en sistemas de calefacción a gas. Se explica la diferencia entre combustión completa e incompleta, cómo interpretar los colores de la flama y qué significan en cuanto a eficiencia y seguridad. Además, se introduce el concepto de aire primario y aire secundario, junto con el efecto Venturi y el funcionamiento de los quemadores atmosféricos.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122576225?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Fundamentos de combustión y análisis de flama\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 19, 40, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (176, 13, 35, 'Mezclas aire-gas y cálculos de combustión', 'En esta lección aprenderás a identificar cómo las proporciones de aire y gas influyen directamente en la eficiencia y seguridad de la combustión. Se explican los conceptos de flame impingement, límites de inflamabilidad, mezclas ricas o pobres en gas, y cómo calcular los volúmenes de aire, oxígeno y gas natural necesarios para producir energía en BTUs. Además, se revisa la importancia de la correcta ventilación de los gases de combustión.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122576266?badge=0&autopause=0&player_id=0&app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Mezclas aire-gas y cálculos de combustión\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 15, 35, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (177, 13, 35, 'Reguladores y válvulas de gas', 'En esta lección estudiarás cómo funcionan los reguladores de gas y los distintos tipos de válvulas utilizadas en equipos de calefacción. Se explica la diferencia entre gas natural y propano en cuanto a presiones de operación, el principio de ajuste en pulgadas de columna de agua (WC), y el papel de las válvulas solenoides, de diafragma y redundantes en la secuencia de combustión. También se presentan diagramas y figuras de apoyo del libro para comprender mejor la operación de estos componentes críticos.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122576306?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Reguladores y válvulas de gas\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 28, 51, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (178, 14, 31, 'Ley de Dalton (presiones parciales) + Introducción a Energía', 'Se cierran los ejercicios de práctica, se introduce la Ley de Dalton (P_total = Σ P_i) para explicar el efecto de no condensables (aire) en sistemas de refrigeración, y se abre la introducción a Energía (conservación, formas, eficiencia) como puente al siguiente bloque.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122397233?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Ley de Dalton (presiones parciales) + Introducción a Energía\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 25, 16, 0, 8, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (179, 14, 31, 'Instrumentación en campo: termopar tipo K, ΔT de aire y chequeos rápidos', 'Uso correcto del termopar tipo K con multímetro para medir temperaturas de suministro y retorno, calcular ΔT y realizar chequeos rápidos de desempeño. Colocación correcta de la sonda, tiempo de estabilización, y notas sobre resistencia/ohmios en verificaciones complementarias.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122385117?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Instrumentación en campo: termopar tipo K, ΔT de aire y chequeos rápidos\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 25, 50, 0, 9, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (180, 16, 19, 'Seguridad en el sitio de trabajo con refrigerantes A2L', 'En esta lección aprenderás las medidas de seguridad necesarias al trabajar con refrigerantes A2L en campo. Se explican los procedimientos de bloqueo y etiquetado de energía (lockout/tagout), la importancia de la ventilación, el uso correcto del equipo de protección personal (PPE), y el empleo de herramientas libres de chispa (spark free). También se aborda cómo pequeños descuidos pueden poner en riesgo la vida del técnico', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122956394?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Seguridad en el sitio de trabajo con refrigerantes A2L\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 18, 1, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (181, 16, 19, 'Riesgos eléctricos, flujo de aire y mitigación de fugas en sistemas A2L', 'En esta lección se profundiza en la importancia de la seguridad eléctrica y el manejo del flujo de aire en sistemas con refrigerantes A2L. El instructor explica cómo usar el multímetro de manera correcta, el procedimiento “vivo o muerto”, y la necesidad de cumplir siempre con OSHA. Además, se aborda el concepto de airflow adecuado, la limpieza de coils para garantizar transferencia de calor, y la mitigación de fugas mediante sensores que activan ventiladores internos como medida de prevención frente a riesgos de ignición.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122960660?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Riesgos eléctricos, flujo de aire y mitigación de fugas en sistemas A2L\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 14, 50, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (182, 16, 19, 'Nuevos refrigerantes y clasificación ASHRAE 34', 'En esta lección se introducen los nuevos refrigerantes que reemplazarán progresivamente a los de uso común como el R-410A. Se estudian mezclas como el 448A, el 454B, el R32 y los hidrocarburos (R290, R600). Además, se explica la clasificación ASHRAE 34, que organiza a los refrigerantes según su toxicidad y nivel de flamabilidad. El objetivo es que el técnico comprenda las propiedades de cada refrigerante, sus riesgos y la importancia de recibir capacitación especial antes de manipularlos.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122960986?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Nuevos refrigerantes y clasificación ASHRAE 34\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 15, 50, 0, 4, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (183, 16, 19, 'Límite inferior de flamabilidad y normas del NEC', 'En esta lección se analizan los conceptos fundamentales de flamabilidad en refrigerantes A2L, incluyendo el LFL (Lower Flammability Limit), las pruebas de propagación de llama y la clasificación 2L. El instructor explica prácticas prohibidas como el “palm down” y detalla cómo manipular tanques de refrigerantes flamables. Finalmente, se presentan las normas del National Electrical Code (NEC) que regulan el uso de equipos y herramientas en ambientes con gases inflamables.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122961174?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Límite inferior de flamabilidad y normas del NEC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 36, 0, 5, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (184, 13, 36, 'Tipos de válvulas de gas: funcionamiento y características', 'En esta lección se analizan los diferentes tipos de válvulas utilizadas en sistemas de calefacción a gas. Se estudia el funcionamiento de la válvula con motor y varilla, la válvula combinación (Gas Valve Combination), la Standing Pilot, la Intermittent Pilot y la Direct Ignition. El objetivo es que el estudiante comprenda cómo cada válvula controla el flujo de gas, sus mecanismos de seguridad y las aplicaciones en equipos residenciales y comerciales.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122958901?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Tipos de válvulas de gas: funcionamiento y características\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 25, 55, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (185, 13, 36, 'Regulación del gas, combustión y tipos de combustibles', 'En esta lección se estudian los reguladores de gas y su función en los sistemas de calefacción. Se analizan los módulos electrónicos de control (IFC y otros), los modos de calefacción en equipos modernos (low heat y high heat), así como las características de los diferentes combustibles utilizados: gas natural, propano y butano. También se revisan las medidas de presión, la importancia de la combustión completa y los ajustes de las válvulas para evitar riesgos de monóxido de carbono.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122959469?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Regulación del gas, combustión y tipos de combustibles\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 4, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (186, 13, 37, 'Fundamentos: manifold, orificio y tipos de quemadores', 'En esta primera lección el instructor introduce los componentes básicos del sistema de calefacción a gas. Se estudia el manifold, los orificios y los quemadores, entendiendo cómo el gas fluye, se mezcla con el aire y se produce la combustión. También se presentan los diferentes tipos de quemadores y la importancia del aire primario y secundario para lograr una combustión eficiente.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122959984?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Fundamentos: manifold, orificio y tipos de quemadores\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 25, 51, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (187, 13, 37, 'Cálculo de Temperature Rise y CFM en hornos de gas', 'En esta lección se explican los fundamentos del cálculo de temperatura en calefacción (Temperature Rise) y cómo este parámetro se relaciona con la eficiencia del equipo. El instructor presenta la fórmula de CFM, analiza cómo calcular el flujo de aire necesario y muestra ejemplos prácticos con diferentes lecturas de temperatura. Además, se enseña cómo ajustar la velocidad del blower y comprender los efectos que esto tiene en la temperatura y en el desempeño de la máquina.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122960184?badge=0&autopause=0&player_id=0&app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Cálculo de Temperature Rise y CFM en hornos de gas\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 34, 8, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (188, 13, 37, 'Medición avanzada: amperaje, watts y ajustes de blower', 'En esta lección se profundiza en la práctica de medición de temperatura y flujo de aire en hornos de gas. El instructor enseña cómo calcular los watts del motor y sumarlos al análisis del sistema, cómo medir amperaje y voltaje, y cómo estos influyen en la eficiencia. También se revisa el concepto de Sweet Spot (punto óptimo de trabajo), y se muestran las consecuencias de un mal ajuste de ductos o del blower.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122960434?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Medición avanzada: amperaje, watts y ajustes de blower\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 22, 9, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (189, 16, 38, 'Introducción y fundamentos del recobrado de refrigerantes', 'En esta lección el instructor presenta los fundamentos del proceso de recobrado de refrigerantes según la normativa del EPA. Se analizan los refrigerantes que deben recuperarse obligatoriamente, aquellos que están exentos, y la diferencia entre recobrado, reciclado y reclamación. Además, se explican las consecuencias legales y ambientales de no cumplir con estas regulaciones y se presentan las razones principales por las que un técnico debe realizar este procedimiento.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122992841?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Introducción y fundamentos del recobrado de refrigerantes\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 22, 7, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (190, 16, 38, 'Niveles de recuperación y prácticas seguras en sistemas HVAC', 'En esta lección se estudian los niveles de vacío exigidos por el EPA según el tipo de sistema y la cantidad de refrigerante. El instructor explica las prácticas recomendadas para asegurar una recuperación eficiente y evitar la contaminación del refrigerante, el daño al equipo o la formación de ácidos. También se abordan los riesgos de humedad, suciedad y gases no condensables dentro del sistema.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122993948?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Niveles de recuperación y prácticas seguras en sistemas HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 14, 49, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (191, 16, 38, 'Evacuación, triple vacío y setup del sistema de recobrado', 'En esta lección se estudia en detalle el proceso de evacuación de sistemas de refrigeración, incluyendo la diferencia entre desgasificación y deshidratación, el uso del vacuómetro y la lectura en micrones. Se explica el procedimiento del triple vacío y las precauciones al trabajar con humedad atrapada. Finalmente, el instructor muestra cómo realizar un setup de recobrado de forma práctica, conectando manifold, tanque, filtro y máquina de recuperación según las normas del EPA.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122994180?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Evacuación, triple vacío y setup del sistema de recobrado\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 27, 32, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (192, 16, 38, 'Procedimiento de vacío y práctica con bombas de vacío', 'En esta lección se explica detalladamente cómo realizar el procedimiento de vacío en un sistema de refrigeración. El instructor enseña la correcta conexión de mangueras, uso del manifold, inspección de sellos y válvulas, y la importancia de mantener el aceite de la bomba en buen estado. Además, se analiza cómo interpretar correctamente las lecturas en micrones y por qué no se debe confiar únicamente en las pulgadas de mercurio. El objetivo es que el estudiante domine el setup práctico y las buenas prácticas para asegurar un vacío adecuado antes de cualquier carga de refrigerante.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122994434?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Procedimiento de vacío y práctica con bombas de vacío\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 24, 9, 0, 4, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (193, 18, 39, 'Fundamentos de la refrigeración y rangos de temperatura', '
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (194, 18, 39, 'BTU, tonelada de refrigeración y transferencia de calor', 'Esta lección desarrolla con rigor los conceptos de calor sensible y latente aplicados al ejemplo del hielo: 144 BTU para derretir 1 lb a 32 °F, y la derivación a 1 tonelada = 12,000 BTU/h. Se aclara la diferencia entre refrigeración vs calefacción (la primera remueve calor; la segunda lo aporta), y se explica la transferencia de calor por conducción e infiltración/convección, junto con las condiciones de diseño (95 °F bulbo seco exterior, 75 °F interior). Se cierra destacando por qué el condensador debe operar a temperatura mayor que el ambiente para que exista transferencia.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123041936?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"BTU, tonelada de refrigeración y transferencia de calor\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 28, 4, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (195, 18, 39, 'Ciclo de refrigeración y componentes: del compresor al superheat', 'Se detalla el ciclo de refrigeración con sus cuatro componentes principales (compresor, condensador, dispositivo de expansión, evaporador) y el recorrido del refrigerante a través de cambios de estado (vapor ↔ líquido ↔ mezcla saturada). Se explica punto de ebullición, estado saturado y superheat, el rol del blower y la relación temperatura-presión. Se ubican temperaturas típicas (p. ej., condensación ~125 °F cuando afuera hay 95 °F). Se cierra con aplicaciones: alta, media y baja temperatura y la importancia de aceites compatibles con el refrigerante.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123374642?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Ciclo de refrigeración y componentes: del compresor al superheat\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 27, 59, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (196, 13, 40, 'Intercambiadores de Calor: Tipos, Materiales y Fallas Comunes', 'En esta lección aprenderás qué son los intercambiadores de calor en los hornos de gas, los diferentes materiales en que se fabrican y cómo su diseño influye en la eficiencia y seguridad. El instructor explica problemas típicos como la corrosión, fisuras y fallas por mala instalación, además de mostrar la importancia de mantener separados los gases de combustión del aire que se distribuye en los espacios habitados.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123419286?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Intercambiadores de Calor: Tipos, Materiales y Fallas Comunes\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 27, 25, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (197, 13, 40, 'Fan Limit Switch, High Limit y Pilotos en Hornos de Gas', 'En esta lección se estudian los controles de ventilador y límite de seguridad en los hornos de gas. Aprenderás cómo funcionan el fan limit switch y el high limit switch, por qué nunca deben ser puenteados, y qué riesgos existen si fallan. También se explican ejemplos reales de fallas en campo, se introduce el tema de los rollout switches y se analizan los diferentes tipos de pilotos (aerated y non-aerated), junto con el papel del termocouple como dispositivo de seguridad.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123419578?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Fan Limit Switch, High Limit y Pilotos en Hornos de Gas\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 23, 11, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (198, 13, 41, 'Componentes del Furnace y Hornos Natural Draft', 'En esta lección se estudian los componentes principales de un furnace, cómo funcionan los sensores de seguridad, y se comparan los equipos modernos con los hornos antiguos tipo Natural Draft. También se explican las categorías de los hornos a gas (1 a 4) y sus niveles de eficiencia, preparando al estudiante para entender las diferencias entre diseños convencionales y equipos de alta eficiencia.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123419746?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Componentes del Furnace y Hornos Natural Draft\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 10, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (199, 13, 41, 'Pilotos y Dispositivos de Seguridad en Hornos a Gas', 'En esta lección se estudian los diferentes tipos de pilotos (aereados, no aereados, intermitentes y standing pilot), junto con los dispositivos de seguridad encargados de verificar la presencia de flama. Se analizan en detalle el thermocouple, thermopile, bimetallic strip y el bulbo remoto con líquido, explicando cómo funcionan, qué voltajes generan y cómo se prueban. También se muestra cómo estos dispositivos interactúan con la válvula de gas para mantener un funcionamiento seguro del furnace.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123419890?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Pilotos y Dispositivos de Seguridad en Hornos a Gas\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 32, 57, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (200, 13, 41, 'Termostatos Antiguos, Heat Anticipator y Sistemas de Ignición Intermitente', 'En esta lección se analizan los termostatos antiguos usados en hornos de gas, explicando su funcionamiento sin pilas ni neutro y cómo se conectan directamente a la válvula de gas. Se estudia el papel del heat anticipator, dispositivo encargado de apagar la calefacción con anticipación para evitar sobrecalentamiento en el espacio. Finalmente, se introducen los sistemas de ignición intermitente (Intermittent Pilot), que encienden el piloto solo cuando hay demanda de calefacción, mostrando sus ventajas frente al standing pilot.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123428520?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Termostatos Antiguos, Heat Anticipator y Sistemas de Ignición Intermitente\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 16, 54, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (201, 13, 41, 'Direct Spark Ignition y Sistemas de Alta Eficiencia', 'En esta lección se estudian los sistemas modernos de ignición en hornos a gas: Direct Spark Ignition (DSI) y Hot Surface Ignition (HSI). El instructor explica cómo funcionan estos sistemas sin piloto permanente, la importancia del sensor de flama y la rectificación de corriente para confirmar la ignición. También se analiza la secuencia de arranque en hornos de alta eficiencia, el papel del pre-purge, y la necesidad de aterrizar adecuadamente el sistema. La clase cierra con una demostración práctica y comentarios finales.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123428597?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Direct Spark Ignition y Sistemas de Alta Eficiencia\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 24, 6, 0, 4, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (202, 13, 43, 'Pruebas iniciales: purga, sensor de flama y Pressure Switch', 'En esta lección aprenderás a identificar el proceso de prepurga de la máquina, cómo se realizan las pruebas al sensor de flama y la forma correcta de comprobar el Pressure Switch utilizando instrumentos profesionales. También se muestran mediciones de voltaje en el Igniter y la válvula de gas, destacando los errores comunes que deben evitarse al hacer estas verificaciones en campo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123775301?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Pruebas iniciales: purga, sensor de flama y Pressure Switch\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 59, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (203, 13, 43, 'Sensores de seguridad, códigos de error y diagnóstico avanzado', 'En esta lección se estudian los sensores de seguridad de la máquina (High Limit, Rollout y Auxiliar), su funcionamiento en serie y cómo afectan al ciclo de encendido. También se enseña a interpretar los códigos de error que genera la tarjeta, así como a diferenciar entre fallas por presión, exceso de gas o alineación de quemadores. Finalmente, se explica el papel de la corriente alterna y directa en la tarjeta electrónica, reforzando el uso del diagrama eléctrico como herramienta esencial para el diagnóstico profesional.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123775545?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Sensores de seguridad, códigos de error y diagnóstico avanzado\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 18, 26, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (204, 13, 42, 'Fundamentos del sensor de flama y su diagnóstico en campo', 'En esta lección aprenderás el principio de funcionamiento del sensor de flama, cómo la rectificación de flama asegura la combustión segura en los equipos de calefacción y la forma correcta de medir microamperes utilizando un multímetro.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (205, 13, 42, 'Secuencia de operación, diagnóstico del sistema y transformadores adicionales', 'En esta lección aprenderás la secuencia de operación completa de un horno a gas, desde la señal del termostato hasta el encendido de la válvula y el funcionamiento del blower. Se detallan los pasos que ocurren en orden, los errores comunes en el diagnóstico de fallas y la importancia de revisar fusibles y cortos antes de culpar al sensor de flama.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (206, 13, 42, 'Válvula reversible, configuración de termostatos y errores comunes en bombas de calor', 'En esta lección aprenderás el funcionamiento de la válvula reversible en sistemas de bomba de calor, diferenciando cuándo se energiza en modo cooling y cuándo en modo heating según el fabricante.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (207, 13, 44, 'Tipos de aire en combustión y eficiencia en hornos', 'En esta lección se estudian los diferentes tipos de aire involucrados en los procesos de combustión: primario, secundario, diluido y en exceso. Además, se analiza cómo la presencia y control de estos aires afecta la eficiencia de los hornos y furnaces. El instructor compara equipos de diferentes niveles de eficiencia (70%, 80% y 95%) y explica cómo la condensación y la reducción de temperatura de gases influyen en el diseño y en los materiales utilizados para la salida de gases, como el PVC.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122928399?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Tipos de aire en combustión y eficiencia en hornos\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 11, 54, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (208, 13, 45, 'Introducción a los Combustibles y su Seguridad', 'En esta lección se presenta la importancia de la especialización en calefacción y se inicia el Capítulo 2: Combustibles y sus propiedades. El instructor explica cómo se forman los combustibles fósiles, por qué son considerados recursos no renovables y cuál es su rol en calefacción, transporte y generación de energía. Además, se aborda la seguridad en el manejo del gas natural y LPG, introduciendo conceptos fundamentales como BTU, densidad, gravedad específica, volumen específico y límites explosivos (LEL y UEL).', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123795996?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Introducción a los Combustibles y su Seguridad\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 22, 4, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (209, 13, 45, 'Límites Explosivos y Combustión en Calefacción', 'En esta lección se profundiza en los conceptos de Lower Explosive Limit (LEL) y Upper Explosive Limit (UEL), mostrando cómo influyen en la seguridad y el funcionamiento de los equipos de calefacción. El instructor compara los riesgos del gas natural, propano y butano, y explica cómo las mezclas aire/combustible afectan la combustión. Además, se incluyen ejemplos prácticos de campo y una conexión con el funcionamiento de los motores automotrices.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123796106?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Límites Explosivos y Combustión en Calefacción\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 18, 9, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (210, 13, 46, 'Conceptos básicos de BTU y contenido de calor', 'En esta lección aprenderás los fundamentos de las unidades térmicas británicas (BTU), cómo se definen y cuál es la diferencia entre temperatura e intensidad de calor frente a la cantidad de calor. También verás cómo se expresa el contenido calorífico de distintos combustibles como el gas natural, LPG y butano, junto con ejemplos de cálculo en equipos de calefacción domésticos (ej. un calentador de agua de 40 galones).', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123920151?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Conceptos básicos de BTU y contenido de calor\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 24, 35, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (211, 13, 46, 'Aplicaciones prácticas en calentadores comerciales y restaurantes', 'En esta lección aprenderás a realizar cálculos de contenido de calor y tiempos de calentamiento aplicados a equipos comerciales e industriales. Se explican casos reales con boilers de gran capacidad, calentadores para restaurantes y la importancia del tiempo de recuperación en el suministro de agua caliente. Además, se destacan los errores comunes al seleccionar equipos con menos BTUs de los necesarios.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123920581?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Aplicaciones prácticas en calentadores comerciales y restaurantes\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 16, 47, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (212, 13, 46, 'Cálculos con eficiencia de equipos y ejercicios prácticos', 'En esta lección aprenderás a aplicar el concepto de eficiencia de equipos en los cálculos de BTU. Se explica la diferencia entre input y output, cómo considerar pérdidas de energía y cómo estos factores afectan el tiempo de calentamiento. Además, se realizan ejercicios prácticos paso a paso, incluyendo ejemplos con furnaces de 150,000 BTU y un Water Heater de 60 galones, donde los estudiantes resuelven cálculos con supervisión del instructor.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1123920673?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Cálculos con eficiencia de equipos y ejercicios prácticos\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 20, 11, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (213, 13, 47, 'Clasificación de refrigerantes A2L y requisitos de instalación', 'En esta lección aprenderás los fundamentos sobre la clasificación de los refrigerantes A2L, específicamente el R32. Se explican los requisitos mínimos de espacio para su instalación, los riesgos de colocarlo en áreas reducidas como clósets, y cómo calcular la carga de refrigerante. Además, se aborda la interpretación de datos técnicos en las placas del condensador, la comparación con el refrigerante R410A, y los cálculos básicos de amperaje y protección eléctrica necesarios para la correcta instalación.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124120861?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Clasificación de refrigerantes A2L y requisitos de instalación\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 19, 8, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (214, 13, 47, 'Líneas de refrigeración, trampas y carga adicional en R32', 'En esta lección aprenderás cómo calcular la carga de refrigerante adicional en función de la longitud de las líneas, qué tipos de tuberías deben usarse según el tonelaje y distancia, y la importancia de instalar trampas en la línea de succión para garantizar el retorno del aceite al compresor. También se abordan temas de compatibilidad de aceites, pruebas de presión, procedimientos de vacío y la importancia del superheat y subcooling en la carga del sistema. Finalmente, se introduce el uso de sensores de seguridad en equipos modernos con R32.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124120941?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Líneas de refrigeración, trampas y carga adicional en R32\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 19, 57, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (215, 13, 47, 'Superheat, Subcooling y sistemas avanzados con R32', 'En esta lección se profundiza en el uso de pistones y válvulas de expansión (TXV), el ajuste de superheat y subcooling, y cómo los fabricantes proporcionan tablas específicas para cada modelo. También se revisan las configuraciones de instalación (horizontal, vertical, ad-flo), la compatibilidad de tarjetas electrónicas con sensores de fuga, y las nuevas medidas de seguridad en equipos con refrigerante R32. Finalmente, se aborda la importancia del mantenimiento, los riesgos de un mal vacío, y las razones por las cuales no se recomienda realizar pump down en estos sistemas.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124121031?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Superheat, Subcooling y sistemas avanzados con R32\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 20, 3, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (216, 13, 48, 'Refrigerantes modernos y la importancia de certificarse', 'En esta lección aprenderás sobre los nuevos refrigerantes R32 y 454, su uso en el mercado actual y los equipos necesarios para manipularlos de forma segura. También conocerás los tipos de certificaciones que debe obtener un técnico HVAC, incluyendo la relacionada con refrigerantes y calefacción, así como los materiales de estudio disponibles (libros y accesos digitales al EPA). Finalmente, el instructor enfatiza la relevancia de la certificación para ejercer profesionalmente en la industria.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124121296?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Refrigerantes modernos y la importancia de certificarse\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 25, 37, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (217, 13, 48, 'Fundamentos de combustión y el triángulo de la combustión', 'En esta lección el estudiante comprenderá qué es la combustión, sus diferentes tipos y los factores que la hacen eficiente o deficiente. Se estudia el triángulo de la combustión (combustible, oxígeno y calor), cómo estos elementos interactúan y qué sucede si alguno falta. Además, se analizan anécdotas de campo que demuestran la importancia de un diagnóstico técnico correcto, evitando gastos innecesarios y mejorando la seguridad.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124121458?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Fundamentos de combustión y el triángulo de la combustión\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 23, 37, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (218, 13, 48, 'Tipos de combustión y prevención de riesgos con monóxido de carbono', 'En esta lección se estudian los distintos tipos de combustión: perfecta, completa e incompleta. Se analizan las reacciones químicas del metano, el balance de oxígeno necesario y los efectos de una mala mezcla aire-combustible. El instructor explica cómo identificar una combustión deficiente y la peligrosidad del monóxido de carbono (CO). También se revisa el uso de analizadores de combustión y detectores de CO como parte esencial del trabajo seguro del técnico HVAC.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124121500?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Tipos de combustión y prevención de riesgos con monóxido de carbono\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 18, 36, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (219, 13, 49, 'Combustión incompleta: causas, reacciones y riesgos', 'En esta lección aprenderás qué es la combustión incompleta, cuáles son las condiciones que la provocan y por qué representa un riesgo para la salud y la eficiencia de los equipos. Se analizan las reacciones químicas del metano con oxígeno insuficiente, los efectos del intercambiador de calor craqueado, la composición del aire y el papel del nitrógeno en el proceso de combustión.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1122928947?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Combustión incompleta: causas, reacciones y riesgos\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 32, 34, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (220, 18, 50, 'Introducción al ciclo de refrigeración y uso de visores de vidrio', 'En esta lección el instructor explica la importancia de comprender el ciclo de la refrigeración para los técnicos en aire acondicionado y refrigeración. Se aborda por qué no es posible ver el refrigerante dentro de las tuberías, cómo los accesorios como los visores de vidrio (side glass) ayudan a detectar el estado del refrigerante, y qué instrumentos son esenciales para realizar diagnósticos. El estudiante aprenderá la base conceptual que servirá para todas las prácticas posteriores.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124316721?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Introducción al ciclo de refrigeración y uso de visores de vidrio\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 15, 34, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (221, 18, 50, 'Pruebas con refrigerantes y transferencia de calor', 'En esta lección se realizan experimentos prácticos con tanques de refrigerante sumergidos en agua con hielo para demostrar la relación entre presión, temperatura y transferencia de calor. El instructor explica cómo las leyes de la termodinámica rigen el comportamiento del refrigerante y cómo los cambios de estado (sólido, líquido, gaseoso) dependen de la energía absorbida o liberada. Los estudiantes comprenderán la importancia de los conceptos de calor sensible y calor latente, aplicados directamente a la refrigeración.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124323578?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Pruebas con refrigerantes y transferencia de calor\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 16, 10, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (222, 18, 50, 'Compresores y chillers en sistemas de refrigeración', 'En esta lección se estudian los diferentes tipos de compresores utilizados en refrigeración y aire acondicionado, incluyendo recíprocos, rotativos, scroll y semiherméticos. El instructor explica sus características, funcionamiento, aplicaciones y costos, destacando la importancia de seleccionar el compresor adecuado según la capacidad y el tipo de sistema. Además, se presenta el funcionamiento de chillers de agua y aire, mostrando sus componentes internos y externos, y cómo se integran en instalaciones de mayor escala como hoteles, fábricas o estadios.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124323867?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Compresores y chillers en sistemas de refrigeración\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 37, 33, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (223, 18, 51, 'El compresor y la línea de descarga', 'En esta lección conocerás a detalle el papel del compresor como “el corazón del sistema de refrigeración”. Aprenderás cómo funciona la línea de descarga y la línea de succión, la diferencia de presiones y temperaturas en cada una, y qué significa el término superheat (sobrecalentamiento). También verás cómo el calor absorbido en diferentes puntos afecta al compresor y cómo se debe manejar para garantizar un buen funcionamiento del sistema.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124323323?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"El compresor y la línea de descarga\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 20, 48, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (224, 18, 51, 'Trampas de aceite y problemas de instalación', 'En esta lección aprenderás qué son las trampas de aceite (oil traps), por qué son vitales para el buen funcionamiento del compresor y cómo deben instalarse según la posición del equipo. También verás errores comunes en las instalaciones, los riesgos de usar dispositivos como hard start kits para “revivir” compresores dañados, y la importancia de seguir manuales y códigos de instalación.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124328290?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Trampas de aceite y problemas de instalación\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 19, 46, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (225, 18, 51, 'Tipos de compresores en refrigeración', 'En esta lección aprenderás los diferentes tipos de compresores que se utilizan en sistemas de aire acondicionado y refrigeración. Mario explica cómo funcionan, sus ventajas, limitaciones y aplicaciones según el tamaño y capacidad del sistema. Además, se presentan referencias directas al libro de texto para reforzar lo aprendido.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124328460?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Tipos de compresores en refrigeración\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 31, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (226, 18, 51, 'El condensador y el subenfriamiento', 'En esta lección aprenderás la función del condensador dentro del ciclo de refrigeración, su papel en la remoción de calor y los factores que afectan su eficiencia. También verás cómo se produce el subenfriamiento (subcooling), su importancia en el cambio de estado del refrigerante y cómo identificar este proceso con ejemplos claros y analogías prácticas.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124328889?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"El condensador y el subenfriamiento\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 13, 37, 0, 4, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (227, 18, 51, 'Subenfriamiento práctico y dispositivos de expansión', 'En esta lección aprenderás cómo calcular el subenfriamiento (subcooling) en campo utilizando tablas de presión y temperatura. Además, se introduce el dispositivo de expansión (metering device), el fenómeno del flash gas, y la importancia de filtros, desecadores y mufflers en el sistema. La clase cierra con recomendaciones prácticas de instalación y mantenimiento.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124329153?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Subenfriamiento práctico y dispositivos de expansión\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 29, 7, 0, 5, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (228, 18, 39, 'Relación presión–temperatura y punto de ebullición', 'En esta lección aprenderás cómo la presión y la temperatura se relacionan directamente en el comportamiento de líquidos y gases. Se analiza el agua como ejemplo de transporte de energía de calor y se contrasta con los refrigerantes, que permiten controlar la temperatura modificando la presión dentro de un sistema sellado. Se introducen los conceptos de sistema cerrado, vacío, y cómo esto permite que los refrigerantes sean aprovechados para conservar productos y generar confort.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124071394?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Relación presión–temperatura y punto de ebullición\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 34, 17, 0, 4, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (229, 18, 39, 'Buenas prácticas de carga y vacío en refrigeración', 'Aquí se explican los procedimientos correctos de carga de refrigerante: por qué debe hacerse en líquido, los riesgos de cargar en vapor, y la función de los dosificadores/atomizadores para ajustar el flujo sin dañar al compresor. Se introduce el uso de la báscula para carga por peso, y se aclara el mal uso del término “Freón”. También se enfatiza la importancia de un buen vacío previo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124336897?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Buenas prácticas de carga y vacío en refrigeración\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 27, 16, 0, 5, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (230, 18, 39, 'Dispositivos de expansión y transferencia de calor', 'Esta lección aborda los dispositivos de expansión (capilar, pistón, válvula de expansión termostática), su función de restringir el paso del refrigerante y permitir la caída de presión/temperatura. Se explica cómo ocurre la condensación y la evaporación, y se aclara que el refrigerante no se gasta en un sistema sellado. Se refuerza el concepto de superheat como protección para el compresor y la necesidad de mediciones correctas.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124336988?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Dispositivos de expansión y transferencia de calor\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 31, 28, 0, 6, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (231, 18, 39, 'Tablas presión–temperatura y vapor sobrecalentado', 'En esta lección se aprende a utilizar las tablas P–T para identificar la relación presión–temperatura de un refrigerante en estado saturado. Se aclara por qué un refrigerante sobrecalentado no sigue la tabla de saturación y cómo calcular presiones correspondientes. Se muestran ejemplos con R-22 y un tanque de R-404A, además de las condiciones de bulbo seco y mojado. Se analiza también cómo el tamaño del condensador afecta la capacidad de disipar calor.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124343025?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Tablas presión–temperatura y vapor sobrecalentado\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 27, 46, 0, 7, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (232, 18, 51, 'El Dispositivo de Medición y los Cuatro Componentes del Sistema de Refrigeración', 'En esta clase se profundiza en el funcionamiento del metering device o dispositivo de medición, parte clave del sistema de refrigeración. El instructor explica los diferentes tipos de válvulas (TXV, electrónica, automática, tubo capilar y orificio fijo) y cómo cada una regula el flujo del refrigerante.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (233, 18, 53, 'Valor del oficio y primeras experiencias', 'En esta primera lección, Mario comparte una mirada humana y motivadora sobre los comienzos en el oficio HVAC. A través de sus propias vivencias, enseña la importancia de la constancia, la disciplina y la calidad del trabajo. Los estudiantes conocerán cómo las primeras etapas del aprendizaje pueden ser difíciles, pero también cómo el compromiso con el buen servicio abre oportunidades profesionales y financieras dentro de la industria.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124398794?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Valor del oficio y primeras experiencias\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 19, 50, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (234, 18, 53, 'Casos reales y valor técnico en servicio', 'En esta lección, Mario comparte experiencias de campo que demuestran la diferencia entre un técnico promedio y un verdadero profesional HVAC. A través de anécdotas reales, el instructor enseña la importancia del diagnóstico correcto, la ética en el servicio y el valor del conocimiento técnico frente al simple reemplazo de piezas. El alumno comprenderá cómo un trabajo bien ejecutado genera confianza, ahorro para el cliente y reputación para el técnico.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124402178?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Casos reales y valor técnico en servicio\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 25, 25, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (235, 18, 53, 'Componentes del ciclo: condensador, dew point, bubble point', 'En esta tercera lección, Mario inicia la explicación teórica del ciclo de refrigeración. El estudiante aprenderá a identificar los componentes principales —compresor, condensador, válvula de expansión (TXV) y evaporador— y comprenderá cómo se da la transferencia de calor dentro del sistema. Además, se profundiza en conceptos clave como calor sensible, calor latente, dew point y bubble point, necesarios para entender el funcionamiento térmico del condensador.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124402221?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Componentes del ciclo: condensador, dew point, bubble point\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 23, 14, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (236, 18, 53, 'TXV: prueba, diagnóstico y ajustes de superheat', 'En esta lección final, Mario explica en detalle el funcionamiento de la válvula de expansión termostática (TXV), sus tres presiones de control y la forma correcta de diagnosticar problemas en el sistema.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (237, 18, 54, 'Válvulas de expansión termostática: ecualización interna y externa', 'En esta lección aprenderás a identificar los diferentes tipos de válvulas de expansión termostática utilizadas en sistemas de refrigeración, comprendiendo su funcionamiento, los principios de ecualización de presión (interna y externa) y la correcta aplicación según el número de circuitos del evaporador. El instructor explica errores comunes en campo y su impacto directo en la eficiencia del sistema, estableciendo las bases del control de flujo de refrigerante.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124402116?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Válvulas de expansión termostática: ecualización interna y externa\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 23, 11, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (238, 18, 54, 'Instrumentos para medir temperatura, presión y flujo de aire en sistemas de aire acondicionado', 'En esta lección aprenderás a identificar y utilizar los principales instrumentos de medición en el campo del aire acondicionado y la refrigeración. El instructor presenta una variedad de equipos, desde termómetros básicos hasta anemómetros profesionales, explicando su principio de funcionamiento, su aplicación práctica y la importancia de realizar mediciones precisas para determinar la cantidad de calor que un sistema es capaz de remover.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124402771?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Instrumentos para medir temperatura, presión y flujo de aire en sistemas de aire acondicionado\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 22, 16, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (239, 18, 54, 'Cálculo práctico de calor sensible: Delta T y eficiencia del sistema', 'En esta lección aprenderás a medir la temperatura de retorno y suministro en un sistema de aire acondicionado para calcular el Delta T (diferencia de temperatura), y con ello determinar la cantidad de calor sensible que el equipo es capaz de remover.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (240, 18, 54, 'Cálculo de entalpía y calor total: psicrometría aplicada al aire acondicionado', 'En esta lección aprenderás a calcular la entalpía total de un sistema de aire acondicionado, combinando el calor sensible y el calor latente.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (241, 18, 52, 'Fundamentos de la Refrigeración y el Ciclo Básico', 'La lección abre con la ambientación del curso y las medidas de seguridad. El instructor explica que el “frío” no existe: lo que percibimos es la ausencia de calor. Desde esa idea, se introduce el concepto de transferencia de energía térmica y cómo el sistema de refrigeración aprovecha esa transferencia para mover calor desde un punto a otro.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124366459?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Fundamentos de la Refrigeración y el Ciclo Básico\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 26, 58, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (242, 18, 52, 'R410A y Diagnóstico del Compresor (Relación de Compresión)', 'Se retoma el ciclo, pero ahora aplicado a un refrigerante moderno: R410A. El instructor muestra cómo se comporta dentro del circuito, con énfasis en las presiones, temperaturas y mezcla de fases.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (243, 18, 52, 'Carga, Amperaje y Evolución de los Refrigerantes', 'El instructor desmonta uno de los mitos más comunes del oficio: “cargar por amperaje”. A la vez, abre un repaso histórico sobre los gases que marcaron cada era de la refrigeración.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (244, 18, 52, 'Refrigerantes de Bajo GWP, Seguridad y Retrofits', 'Se entra a la parte más actual del curso: los refrigerantes de bajo GWP y los retos de manipulación segura en campo, junto con las certificaciones necesarias para trabajar con ellos.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (245, 18, 52, 'Reemplazos y compatibilidad de refrigerantes', 'Esta lección explica las sustituciones más comunes de los refrigerantes tradicionales (R12, R22) y la razón técnica por la cual algunos reemplazos no pueden utilizarse de manera directa. Se profundiza en la compatibilidad entre aceites y las presiones de trabajo de cada mezcla.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124536489?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Reemplazos y compatibilidad de refrigerantes\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 26, 45, 0, 5, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (246, 18, 52, 'Conexión segura de manómetros y prácticas EPA', 'El alumno aprende la correcta conexión del manifold y las mangueras de baja pérdida, siguiendo las normas EPA, para evitar fugas o contaminación del sistema.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124537172?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Conexión segura de manómetros y prácticas EPA\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 30, 13, 0, 6, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (247, 18, 52, 'Superheat y Subcooling', 'Esta lección se enfoca en la medición del Superheat (sobrecalentamiento) y Subcooling (subenfriamiento) usando clampas, interpretando los resultados para diagnosticar el rendimiento real del sistema.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124537191?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Superheat y Subcooling\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 30, 1, 0, 7, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (248, 18, 52, 'TXV, eficiencia y desempeño del sistema', 'En esta parte final se estudia el funcionamiento del TXV (válvula de expansión termostática), el equilibrio térmico del evaporador y la medición de eficiencia real del sistema mediante BTUs y humedad.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1124537219?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"TXV, eficiencia y desempeño del sistema\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 27, 19, 0, 8, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (256, 16, 56, 'Actualización profesional y transición a los nuevos refrigerantes A2L', 'En esta lección, el instructor Mario enfatiza la importancia de mantenerse actualizado en el campo del aire acondicionado y la refrigeración. Explica cómo las certificaciones, en especial el EPA y las de especialidades HVAC, deben renovarse constantemente para seguir al día con los cambios tecnológicos.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (257, 16, 56, 'Bracing y Soldering: Fundamentos técnicos, herramientas y seguridad en HVAC', 'En esta lección, el instructor Mario enseña las diferencias entre Soldering y Bracing, dos técnicas esenciales para unir tuberías en sistemas de aire acondicionado y refrigeración.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (258, 16, 56, 'Seguridad y fundamentos técnicos de los nuevos refrigerantes A2L', 'En esta lección, el instructor Mario introduce formalmente la Sección 2 del curso A2L, donde explica qué son los refrigerantes de bajo potencial de calentamiento global (GWP) y cómo difieren de los tradicionales (R22, R410A, R404C).
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (259, 16, 56, 'Manejo práctico, carga, recuperación y medidas de seguridad con refrigerantes A2L', 'En esta lección, el instructor Mario desarrolla la parte operativa y práctica del curso. Explica cómo deben manipularse los refrigerantes A2L en campo, desde su almacenamiento hasta el proceso de carga, recuperación y ventilación.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (260, 16, 56, 'Pruebas de fugas con nitrógeno y procedimientos de verificación en sistemas A2L', 'En esta lección, el instructor Mario enseña cómo realizar correctamente una prueba de fugas (Leak Test) en sistemas que utilizan refrigerantes A2L.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (261, 16, 56, 'Rastreo de fugas, límites de inflamabilidad y uso de detectores electrónicos para sistemas con refrigerantes A2L', 'En esta lección, el instructor Mario enseña cómo rastrear fugas reales en sistemas que trabajan con refrigerantes A2L, utilizando diferentes herramientas profesionales de detección.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (262, 16, 57, 'Errores comunes con motores ECM y fundamentos del aprendizaje técnico', 'En esta primera lección, Mario introduce un tema fundamental en el área HVAC: los motores ECM y sus errores más comunes en instalaciones mal diseñadas. A través de anécdotas personales, explica cómo las malas prácticas y la falta de fundamentos técnicos pueden llevar a pérdidas económicas y desprestigio profesional.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (263, 16, 57, 'Diferencias entre técnico e instalador: experiencia, práctica y desarrollo profesional', 'En esta segunda lección, Mario conversa directamente con sus alumnos para enseñarles que la verdadera formación de un técnico HVAC se construye en el campo, con práctica constante y bajo supervisión.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (264, 16, 57, 'Refrigerantes A2L, válvulas de alivio y estrategias de mitigación', 'En esta tercera lección, Mario cambia el enfoque hacia la parte normativa y de seguridad del curso, introduciendo los conceptos relacionados con los refrigerantes de baja inflamabilidad A2L.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (265, 16, 57, 'Procedimientos de instalación, limpieza y pruebas de presión en sistemas A2L', 'En esta cuarta lección, Mario lleva a los alumnos a la parte práctica del proceso de instalación. Explica paso a paso cómo realizar una prueba de presión correcta con nitrógeno, cómo limpiar y purgar líneas de refrigeración, y qué precauciones se deben tomar al trabajar con refrigerantes A2L (como R32 o R454B).
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (266, 16, 57, 'Vacío, carga de refrigerante y verificación práctica del sistema', 'En esta quinta lección, Mario lleva a los alumnos al taller para realizar la evacuación, carga y prueba de funcionamiento de un sistema de aire acondicionado con refrigerante A2L.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (267, 16, 57, 'Lectura de parámetros, análisis de rendimiento y cierre del módulo práctico', 'En esta sexta lección, Mario concluye el módulo de instalación y arranque enseñando cómo interpretar correctamente las mediciones de funcionamiento de un sistema HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (268, 16, 57, 'Casos reales, buenas prácticas y cierre del módulo de refrigerantes A2L', 'En esta séptima y última lección, Mario cierra el módulo compartiendo experiencias de campo y errores comunes que suelen cometer incluso técnicos con experiencia.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (269, 14, 31, '? Examen: Especialidad para Aire Acondicionado', 'Este examen está diseñado para evaluar la comprensión teórica del estudiante sobre los principios fundamentales de la refrigeración, abordados en los módulos introductorios de la Especialidad para Aire Acondicionado. A través de preguntas de opción múltiple, se refuerzan conceptos esenciales como:
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (270, 18, 54, 'Examen: Refrigeración y Refrigerantes', 'Este examen evalúa el dominio teórico del estudiante sobre los principios esenciales de la refrigeración y el manejo de refrigerantes, abordando aspectos clave como:
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (271, 16, 58, 'Fundamentos de los Refrigerantes y Principios del Ciclo de Refrigeración', 'En esta primera lección, el instructor introduce los fundamentos técnicos del refrigerante, su comportamiento físico y su papel en el ciclo de refrigeración.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (272, 16, 58, 'Componentes del Sistema de Refrigeración y Arranque Práctico del Equipo', 'En esta segunda lección, el instructor deja la teoría y se adentra en la parte práctica del sistema HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (273, 16, 58, 'Sensores, Cableados y Diagnóstico de Carga Parcial en Sistemas HVAC', 'En esta lección, el instructor profundiza en la parte eléctrica y de control del sistema HVAC, analizando cómo los sensores, termistores y cableados afectan el funcionamiento general.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (274, 16, 58, 'Cálculo del Temperature Differential (TD), Sobrecalentamiento y Subenfriamiento', 'En esta lección, el instructor enseña a interpretar los parámetros fundamentales que determinan el rendimiento de un sistema HVAC:
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (275, 16, 58, 'Componentes de Calefacción, Combustión y Mantenimiento Preventivo en HVAC', 'En esta lección, el instructor profundiza en el circuito de calefacción de los sistemas HVAC, explicando el principio de combustión, transferencia de calor y control de seguridad.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (276, 16, 58, 'Bombas de Calor: Componentes, Funcionamiento y Diagnóstico en Operación Práctica', 'En esta lección, el instructor se centra en las bombas de calor, uno de los sistemas más versátiles del HVAC moderno.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (277, 16, 58, 'Ciclo de Deshielo, Termostatos y Termistores en Bombas de Calor', 'En esta lección final, el instructor enseña el funcionamiento completo del ciclo de deshielo en una bomba de calor, destacando los sensores y controles involucrados: el termostato de deshielo (defrost thermostat), los termistores de serpentín, el temporizador de control y la válvula reversora.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (278, 16, 434, 'Examen: Refrigerantes A2L', 'Este examen tiene como objetivo evaluar el conocimiento teórico de los estudiantes sobre los refrigerantes A2L, enfocado en:
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (279, 11, 23, 'Examen: Diagnóstico de Motores', 'Este examen evalúa la comprensión técnica del estudiante sobre el diagnóstico y solución de fallas en motores eléctricos, enfocado en:
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (280, 16, 433, 'Introducción y conceptos básicos de Airflow', 'En esta primera lección, el instructor introduce los principios básicos del flujo de aire (Airflow) en sistemas HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (281, 16, 433, 'Velocidad, selección de ductos y registros', 'En esta segunda lección, el instructor aplica los conceptos de velocidad y flujo de aire aprendidos anteriormente, enfocándose en la selección adecuada de ductos y rejillas de suministro o retorno.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (282, 16, 433, 'Ejemplo práctico: cálculo de cargas (casas A y B) y sensible heat ratio', 'En esta tercera lección, el instructor lleva la teoría a la práctica mediante el cálculo real del flujo de aire requerido para dos viviendas con diferentes condiciones térmicas.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (283, 16, 433, 'Cálculos numéricos y deducción completa de la fórmula CFM', 'En esta cuarta lección, el instructor realiza el desarrollo completo de la fórmula del CFM, partiendo de los valores de flujo calculados en la lección anterior.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (284, 16, 433, 'Factores prácticos, pérdidas y preparación para instalación', 'En esta quinta lección, el instructor traslada los cálculos teóricos a la realidad práctica del sistema HVAC, explicando cómo los factores físicos y mecánicos afectan el flujo de aire en una instalación.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (285, 16, 433, 'Instalación práctica: montaje del equipo, flaps, atornillado y sellos', 'En esta sexta lección, el instructor lleva a cabo la instalación física del sistema de aire acondicionado, aplicando los cálculos y preparaciones realizadas en las lecciones anteriores.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (286, 16, 433, 'Final de instalación, ajustes, sellos y cierre de la sesión', 'En esta séptima y última lección, el instructor realiza la revisión final del sistema instalado, comprobando sellos, alineaciones, flujo de aire y estabilidad del conjunto.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (287, 16, 434, 'Introducción al Manual D: objetivos, materiales y relación con el Manual J', 'En esta primera lección conocerás los fundamentos del curso sobre diseño de ductos y flujo de aire según el Manual D.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (288, 16, 434, 'Fundamentos del flujo de aire: volumen, velocidad y presión', 'En esta lección aprenderás los principios físicos básicos del flujo de aire que sirven como cimiento para el diseño de ductos según el Manual D.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (289, 16, 434, 'Medición del flujo de aire: instrumentos, técnicas y analogías prácticas', 'En esta lección aprenderás a medir correctamente el flujo de aire dentro de un sistema HVAC usando instrumentos profesionales.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (290, 16, 434, 'Del calor al flujo de aire: conversión de carga térmica a CFM en sistemas HVAC', 'En esta lección se aborda cómo las cargas térmicas obtenidas del Manual J se traducen en flujo de aire (CFM) dentro del diseño de ductos.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (291, 16, 434, 'Selección de rejillas, cálculo de áreas libres y control de velocidad del aire', 'En esta lección, Mario conecta los conceptos de flujo de aire y carga térmica con el diseño físico del sistema de ductos.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (292, 16, 434, 'Filtros, presión estática y herramientas acreditadas para el diseño de ductos', 'En esta lección, Mario explica la influencia de los filtros y de los componentes del sistema en la presión estática total, un factor clave en el diseño de ductos según el Manual D.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (293, 16, 434, 'Aplicación práctica del Manual D: ejercicios, repaso y conclusiones', 'En esta lección final, Mario guía a los estudiantes en la aplicación práctica de los conceptos aprendidos a lo largo del curso.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (294, 13, 49, 'Examen: Curso de Calefacción', 'Este examen tiene como objetivo evaluar los conocimientos adquiridos en el curso Calefacción de AC Volt School. El estudiante será puesto a prueba en temas como fundamentos de sistemas de calefacción, zonificación, funcionamiento de compuertas, controles eléctricos, seguridad, gas, tipos de combustibles, control de temperatura y diagnóstico de fallas comunes. Ideal para reforzar el aprendizaje técnico aplicado en instalaciones residenciales y comerciales HVAC.', 2, '', '', 0, 0, 0, 30, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (295, 15, 435, 'Fundamentos de Electricidad y Seguridad del Técnico', 'En esta primera lección, el instructor Mario introduce la Unidad 12 del libro de estudio, enfocándose en los conceptos básicos de la electricidad y las normas de seguridad que todo técnico HVAC debe dominar antes de trabajar con circuitos energizados.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (296, 15, 435, 'Estructura Atómica y Electricidad Estática', 'En esta lección, el instructor explica cómo la electricidad tiene su origen en la estructura del átomo.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (297, 15, 435, 'Leyes de las Cargas, Magnetismo y Conductores', 'En esta tercera lección, el instructor Mario profundiza en las leyes que gobiernan la atracción y repulsión de las cargas eléctricas, y cómo estos principios también explican el comportamiento del magnetismo.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (298, 15, 436, 'Origen y fundamentos de la electricidad', 'En esta primera lección del módulo de Electricidad, el instructor explica el origen de la electricidad, cómo se produce por medio del magnetismo, y la importancia de los pioneros científicos que hicieron posibles los sistemas eléctricos modernos.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (299, 15, 436, 'Corriente directa y alterna – Aplicaciones prácticas e industriales', 'En esta lección, el estudiante aprenderá la diferencia entre corriente directa (DC) y corriente alterna (AC), sus aplicaciones, ventajas y funcionamiento en los sistemas eléctricos e industriales.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (300, 15, 437, 'Motores monofásicos y el uso del capacitor de arranque', 'En esta lección aprenderás cómo funcionan los motores monofásicos, por qué a veces no pueden arrancar por sí solos y cómo el embobinado de arranque y el capacitor ayudan a resolver este problema. A través de ejemplos prácticos, el instructor explica el concepto de polos magnéticos, fase, torque y cómo se logra el arranque en motores eléctricos tanto pequeños como industriales.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1129078169?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Motores monofásicos y el uso del capacitor de arranque\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 18, 5, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (301, 15, 437, 'Voltaje, Amperaje y Resistencia: Fundamentos Eléctricos', 'En esta lección aprenderás los tres pilares fundamentales de la electricidad: voltaje, corriente (amperaje) y resistencia. El instructor explica sus relaciones, analogías con sistemas hidráulicos, y cómo medirlos en un circuito utilizando instrumentos eléctricos. Además, se introduce el concepto de diferencia de potencial y se prepara el terreno para la siguiente clase sobre la Ley de Ohm.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1129079414?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Voltaje, Amperaje y Resistencia: Fundamentos Eléctricos\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 32, 37, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (302, 15, 437, 'Distribución eléctrica, paneles y sistema de tierra (Ground)', 'En esta lección se analiza cómo se genera, distribuye y utiliza la energía eléctrica desde la planta de potencia hasta los sistemas residenciales e industriales. Se explica el papel de los transformadores, los tipos de servicio (aéreo y subterráneo), la estructura del panel eléctrico y la función del neutral y el ground. Además, se aclaran conceptos críticos como el “corto circuito”, la puesta a tierra y las normas de seguridad. La clase finaliza con una introducción a la Ley de Ohm.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1129079457?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Distribución eléctrica, paneles y sistema de tierra (Ground)\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 28, 15, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (303, 15, 438, 'La Ley de Ohm y su aplicación práctica', 'En esta lección el instructor explica paso a paso la Ley de Ohm, fundamento esencial de la electricidad. Aprenderás cómo se relacionan el voltaje (E o V), la corriente (I) y la resistencia (R), y cómo usar sus fórmulas para resolver problemas eléctricos reales. Además, se presentan ejemplos prácticos con lámparas y motores, así como la introducción al Power Wheel (rueda del poder), una herramienta muy útil para cálculos eléctricos en campo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1129312648?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Basic_Electricity_Magnetism_B4.MOV (Leccion1)\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 27, 15, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (304, 15, 438, 'Circuitos en Serie y Características Eléctricas', 'En esta lección el instructor continúa aplicando la Ley de Ohm, pero ahora la combina con el análisis de circuitos en serie. Aprenderás cómo calcular el consumo total de corriente, resistencia y voltaje en distintos ejemplos prácticos como un contactor, un calentón eléctrico y un circuito con resistencias en serie. También se enfatizan medidas de seguridad al realizar pruebas eléctricas y se explica por qué los circuitos en serie son poco comunes en la industria HVAC, salvo en los sistemas de seguridad.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1129314976?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Circuitos en Serie y Características Eléctricas\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 16, 0, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (305, 15, 439, 'Fundamentos eléctricos, protecciones y caída de voltaje', 'En esta lección, el instructor introduce los principios esenciales de la electricidad aplicada al campo HVAC. Se explican los principales componentes eléctricos utilizados en sistemas de refrigeración y calefacción, su función en la industria, cómo se clasifican, cómo se prueban y qué parámetros nominales deben respetarse (voltaje, amperaje y resistencia).
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (306, 15, 439, 'Caída de voltaje en componentes, Ley de Ohm y resistencia eléctrica', 'En esta lección, el instructor explica de forma práctica cómo la caída de voltaje puede generarse dentro de los propios componentes eléctricos y no solo por distancia. A través de ejemplos y cálculos reales, se muestra cómo identificar variaciones de voltaje, amperaje y resistencia, aplicando la Ley de Ohm (V = I × R).
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (307, 15, 439, 'Cálculos prácticos y análisis de circuitos combinados (serie y paralelo)', 'En esta lección, el instructor guía al estudiante a través de cálculos eléctricos reales aplicando la Ley de Ohm y las fórmulas de potencia para analizar circuitos en serie, paralelo y combinados.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (308, 15, 440, 'Circuitos serie-paralelo: fundamentos y primer cálculo de resistencia total', 'En esta primera lección, el instructor Mario explica cómo identificar y diferenciar los circuitos en serie, en paralelo y los combinados (serie-paralelo). A través de ejemplos visuales y cálculos paso a paso, los estudiantes aprenden a aplicar la Ley de Ohm para determinar la resistencia total en un circuito mixto.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (309, 15, 440, 'Medición práctica de resistencias y relación entre resistencia y consumo de corriente', 'En esta lección, Mario lleva los conceptos teóricos de resistencia al campo práctico. Los estudiantes aprenden a medir resistencias reales en motores, contactores, transformadores y capacitores, utilizando instrumentos de medición.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (310, 15, 440, 'Uso del multímetro, impedancia y diagnóstico de componentes eléctricos', 'En esta lección, el instructor Mario enseña a los estudiantes el uso correcto del multímetro digital, explicando cada función del selector central: voltaje AC/DC, continuidad, ohmios, microfaradios, temperatura y más.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (311, 15, 440, 'Aplicación real: cálculo de resistencia total, amperaje y potencia en un sistema HVAC', 'En esta lección final, los estudiantes integran todos los conocimientos previos sobre resistencia, corriente, voltaje e impedancia.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (312, 15, 441, 'Cálculo de resistencias individuales y totales en circuitos paralelos', 'En esta primera lección, el instructor repasa los fundamentos eléctricos aplicados al HVAC, enfocándose en los circuitos paralelos.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (313, 15, 441, 'Cálculo de consumo, amperaje y ahorro energético en un proyecto de iluminación industrial', 'En esta lección, el instructor Mario presenta un caso práctico real aplicado a la industria: el reemplazo de un sistema de iluminación antigua por luces LED en una planta de producción.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (314, 15, 441, 'Análisis energético y funcionamiento de transformadores, solenoides y capacitores', 'En esta lección, el instructor profundiza en la relación entre el consumo eléctrico y los componentes electromagnéticos que intervienen en los sistemas HVAC y en las instalaciones industriales.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (315, 15, 441, 'Relés, contactores, fusibles y breakers: protección y control eléctrico en el HVAC', 'En esta lección, el instructor se enfoca en los elementos de control y protección eléctrica más utilizados en el área HVAC: relés, contactores, transformadores, fusibles, breakers y capacitores.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (316, 15, 441, 'Identificación de voltajes, códigos de color y responsabilidades del técnico HVAC', '', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1129954222?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Identificación de voltajes, códigos de color y responsabilidades del técnico HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 24, 58, 0, 5, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (317, 15, 442, 'Paneles eléctricos, neutro, tierra y distribución de fases', 'En esta lección, el instructor Mario explica el funcionamiento del sistema de distribución eléctrica en una instalación HVAC: la diferencia entre main panel y subpanel, el papel de las barras de neutro y tierra, el uso del main bonding jumper, y cómo medir correctamente los voltajes entre fases. También se introduce el concepto del “wild leg” o “high leg” en sistemas trifásicos y su importancia en el trabajo con compresores y motores eléctricos.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1129955566?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Paneles eléctricos, neutro, tierra y distribución de fases\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 34, 5, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (318, 15, 442, 'Tipos de breakers, distribución eléctrica y normas de seguridad', 'En esta lección, el instructor Mario explica en profundidad cómo funcionan los breakers eléctricos (interruptores automáticos), sus diferentes tipos —simples, dobles y trifásicos— y cómo se instalan correctamente dentro de un panel. También aborda conceptos de seguridad, la importancia del orden de fases, y qué errores deben evitarse para prevenir descargas eléctricas o fallas en equipos HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (319, 15, 442, 'Diagnóstico de compresores monofásicos y trifásicos', 'En esta lección práctica, el instructor Mario guía paso a paso el procedimiento profesional para diagnosticar el estado de un compresor eléctrico, tanto monofásico como trifásico.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (320, 15, 443, 'Fundamentos de magnetismo y principio de los transformadores', 'En esta primera lección el instructor presenta los fundamentos del magnetismo y su vínculo con la electricidad.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (321, 15, 443, 'Transformadores y capacitores: principios de funcionamiento, VA y tipos de arranque', 'En esta segunda lección, el instructor profundiza en el funcionamiento de los transformadores, introduciendo el concepto de consumo en VA (volt-amperios) y su relación con el voltaje y la corriente.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (322, 15, 443, 'Lectura del nameplate de motores eléctricos y análisis de sus características', 'En esta tercera lección, el instructor explica detalladamente cómo leer, interpretar y comprender la placa de datos (nameplate) de un motor eléctrico, tanto monofásico como trifásico.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (323, 15, 443, 'Aplicaciones prácticas: compresores, rotación de motores y selección de reemplazos', 'En esta última lección, el instructor lleva a la práctica los conocimientos adquiridos sobre transformadores, capacitores y lectura de nameplates, aplicándolos al diagnóstico de compresores eléctricos y motores en sistemas de refrigeración.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (324, 15, 444, 'Identificación del Común, Start y Run en Motores Eléctricos', 'En esta lección, el instructor guía a los estudiantes en la práctica de medición de resistencias eléctricas en motores, utilizando un multímetro para identificar correctamente los terminales Common (C), Start (S) y Run (R).
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (325, 15, 444, 'Diagnóstico eléctrico y medición de parámetros en compresores', 'En esta lección aprenderás a diagnosticar un compresor midiendo correctamente las presiones de succión y descarga, así como los valores eléctricos de voltaje, corriente y consumo real. El instructor explica paso a paso cómo interpretar el Running Load Amperage (RLA) y el Locked Rotor Amperage (LRA), cómo calcular las variaciones porcentuales admisibles y cómo identificar fallas por exceso de consumo o caídas de voltaje. También se refuerzan los conceptos de seguridad eléctrica, enfatizando la importancia de comprender el flujo de corriente y la medición correcta de voltajes en equipos de refrigeración.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1130368993?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Diagnóstico eléctrico y medición de parámetros en compresores\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 26, 32, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (326, 15, 444, 'Motores eléctricos: funcionamiento, polos y sincronía magnética', 'En esta lección el instructor Mario explica en detalle los fundamentos de los motores eléctricos, sus tipos y su funcionamiento interno. A través de ejemplos prácticos, enseña cómo calcular las revoluciones por minuto (RPM) de un motor en función del número de polos, el voltaje y la frecuencia de operación. Además, diferencia los motores asincrónicos de los sincrónicos, explicando conceptos clave como el campo magnético, el rotor, el estator y el slippage (retraso). La lección concluye con la aplicación práctica de diagnóstico de motores mediante la medición de revoluciones reales.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1130368738?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Motores eléctricos: funcionamiento, polos y sincronía magnética\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 18, 50, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (327, 15, 445, 'Fundamentos de los capacitores en motores eléctricos: función, tipos y principios de operación', 'En esta primera lección, el instructor introduce el tema de los capacitores y su papel fundamental en los motores eléctricos de arranque y de trabajo.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (328, 15, 445, 'Cómo descargar un capacitor de forma segura: resistores de descarga, precauciones y práctica técnica', 'En esta segunda lección, el instructor aborda uno de los temas más importantes en la manipulación de componentes eléctricos: la descarga segura de capacitores.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (329, 15, 445, 'Interpretación del código de colores en resistores y su función en circuitos de descarga', 'En esta tercera lección, el instructor enseña cómo leer e interpretar correctamente los valores de resistencia eléctrica mediante el código de colores impreso en los resistores.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (330, 15, 445, 'Cómo medir capacitores y resistores con multímetro: pruebas, diagnóstico y seguridad', 'En esta cuarta lección, el instructor lleva a la práctica lo aprendido en las secciones anteriores.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (331, 15, 445, 'Cables eléctricos, calibres y aislamientos según norma para motores HVAC', 'En esta quinta lección, el instructor se enfoca en el estudio de los conductores eléctricos utilizados en los sistemas de aire acondicionado.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (332, 15, 445, 'Tipos de motores monofásicos y sus sistemas de arranque: CR, CSCR y CSIR', 'En esta última lección, el instructor introduce los tipos de motores eléctricos monofásicos más utilizados en sistemas de refrigeración y aire acondicionado.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (333, 15, 445, 'Capacitores, semiconductores y fundamentos eléctricos', 'En esta lección, el instructor Mario combina la práctica y la teoría para enseñar los fundamentos esenciales de la electricidad en sistemas HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (334, 15, 446, 'Fundamentos de los motores eléctricos y motores de polo sombreado (Shaded Pole Motors)', 'En esta primera lección, el instructor introduce el tema de los motores eléctricos, destacando su importancia dentro del campo de la refrigeración y aire acondicionado. Explica los fundamentos de diagnóstico, la responsabilidad del técnico al evaluar un motor, y presenta los motores de polo sombreado, describiendo su estructura, funcionamiento, y cómo identificar su dirección de rotación. También se abordan los errores más comunes que ocurren al reemplazarlos en campo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1131183914?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Fundamentos de los motores eléctricos y motores de polo sombreado (Shaded Pole Motors)\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 23, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (335, 15, 446, 'Motores monofásicos y trifásicos: diagnóstico, rotación y errores comunes en campo', 'En esta lección, Mario profundiza en los tipos de motores eléctricos más usados en sistemas de aire acondicionado: monofásicos y trifásicos. Explica cómo distinguirlos, su estructura básica, la función del variador de frecuencia (inverter), y la importancia de elegir el motor adecuado según su rotación. Además, advierte sobre errores típicos cometidos por técnicos y personal de mantenimiento al reemplazar motores y aspas sin considerar la dirección de giro o el balance, lo cual provoca fallas, vibraciones y sobrecalentamiento.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1131184273?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Motores monofásicos y trifásicos: diagnóstico, rotación y errores comunes en campo\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 29, 45, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (336, 15, 446, 'Estructura interna del motor eléctrico y fundamentos de magnetismo en HVAC', 'En esta tercera lección, el instructor analiza en detalle las partes internas de un motor eléctrico, su función individual y cómo interactúan mediante principios de electricidad y magnetismo. Explica el papel del estator, rotor, valeros, housing y embobinado, así como los efectos del ácido y la humedad sobre el esmalte del alambre. Introduce el uso del Megger como herramienta esencial para medir la integridad de la resistencia del embobinado y evitar fallas catastróficas en compresores o motores eléctricos.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1131184527?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Estructura interna del motor eléctrico y fundamentos de magnetismo en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 29, 42, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (337, 15, 447, 'Estructura básica de los motores monofásicos, dual voltage y función del switch centrífugo', 'En esta primera lección, el instructor introduce el tema de los motores eléctricos monofásicos, explicando sus componentes principales, la relación entre los bobinados de arranque y de trabajo, y cómo se comportan cuando el motor opera a diferentes voltajes (115/230 V).
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (338, 15, 447, 'Circuitos de arranque: relé electrónico, relay potencial y motores capacitor start (CSIR)', 'En esta segunda lección, el instructor continúa el estudio de los motores monofásicos, abordando los distintos métodos de arranque que reemplazan al switch centrífugo mecánico.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (339, 15, 447, 'Desfase de corriente, función del capacitor y análisis del ángulo de fase en motores monofásicos', 'En esta tercera lección, el instructor profundiza en el principio del desfase eléctrico entre corriente y voltaje, explicando cómo el capacitor actúa como un phase shifter (desfasador de fase) dentro del circuito del motor.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (340, 15, 447, 'Relación entre polos, frecuencia y velocidad de rotación: comprensión del slip y motores de dos velocidades', 'En esta cuarta lección, el instructor introduce los conceptos de velocidad sincrónica (Synchronous Speed), slip (deslizamiento) y la relación entre el número de polos y la frecuencia eléctrica.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (341, 15, 447, 'Sentido de rotación, conexiones trifásicas y conclusiones sobre los tipos de motores eléctricos', 'En esta quinta y última lección, el instructor aborda el sentido de rotación de los motores eléctricos, tanto monofásicos como trifásicos.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (342, 15, 448, 'Principios de la corriente trifásica, voltajes de línea y diagnóstico inicial de motores eléctricos', 'En esta primera lección, el instructor introduce los principios de la corriente trifásica aplicada a motores eléctricos, un tema esencial dentro del área de refrigeración y aire acondicionado.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (343, 15, 448, 'Configuraciones de conexión en motores eléctricos: Estrella (Y), Paralelo y diagnóstico de tensiones', 'En esta segunda lección, el instructor explica las conexiones internas más comunes en los motores trifásicos: estrella (Y) y paralelo (también conocida como conexión delta o de baja tensión).
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (344, 15, 448, 'Identificación de terminales T1–T9, comprobación de bobinas y sentido de rotación en motores trifásicos', 'En esta tercera lección, el instructor enseña cómo identificar las terminales de un motor trifásico y determinar la configuración interna de sus bobinas.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (345, 15, 448, 'Tipos de motores eléctricos monofásicos: Capacitor Run, Capacitor Start y Shaded Pole (Polo sombreado)', 'En esta cuarta y última lección, el instructor aborda los principales tipos de motores monofásicos utilizados en sistemas de refrigeración y aire acondicionado.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (346, 15, 449, 'Motores monofásicos: tipos, capacitores y sistemas de arranque', 'En esta primera lección, el instructor introduce los principales tipos de motores eléctricos monofásicos usados en equipos de refrigeración y aire acondicionado.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (347, 15, 449, 'Compresores de alta eficiencia, motores ECM y sistemas comunicantes', 'En esta segunda lección, el instructor profundiza en la identificación práctica de compresores y motores de alta eficiencia, ampliando lo aprendido en la Lección 1.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (348, 15, 450, 'Diagnóstico y Conexión Correcta de Motores Trifásicos', 'En esta clase, el instructor Mario realiza una práctica completa de diagnóstico y conexión de motores eléctricos trifásicos. Los estudiantes aprenden a identificar fallas comunes como motores amarrados, fases caídas o bajo voltaje, además de revisar la importancia del “ground loop”, el uso de terminales y las diferencias entre conexiones de bajo y alto voltaje. También se enseña cómo utilizar el voltímetro para verificar las tres fases y cómo detectar si el problema está en el motor o en la fuente de alimentación.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (349, 15, 451, 'Motores eléctricos monofásicos: identificación de terminales, función del capacitor y diagnóstico inicial de compresores', 'En esta primera lección, el instructor Mario introduce los fundamentos de los motores eléctricos monofásicos aplicados a compresores y sistemas de refrigeración domésticos.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (350, 15, 451, 'Capacitores de arranque, relés de corriente y protectores térmicos PTC: funcionamiento y pruebas en compresores', 'En esta segunda lección, el instructor Mario explica en profundidad el funcionamiento del capacitor, el relé de corriente y el protector térmico tipo PTC (Positive Temperature Coefficient).
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (351, 15, 451, 'Pruebas prácticas de diagnóstico: capacitor, relé de corriente y protector térmico PTC en compresores herméticos', 'En esta tercera lección, el instructor Mario realiza las pruebas prácticas con multímetro de los componentes eléctricos estudiados previamente: capacitor, relé de corriente y PTC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (352, 15, 451, 'El PTC en acción: comportamiento térmico, campo magnético y funcionamiento interno del compresor', 'En esta cuarta lección, el instructor Mario profundiza en el principio de funcionamiento del PTC (Positive Temperature Coefficient) y su papel dentro del circuito de arranque del motor eléctrico.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (353, 15, 451, 'Relé de potencial (Potential Relay): principios de operación, desconexión automática del capacitor y control del campo magnético', 'En esta quinta lección, el instructor Mario analiza el relé de potencial (Potential Relay), su principio de funcionamiento basado en la fuerza contraelectromotriz (f.c.e.m.), y cómo este dispositivo desconecta automáticamente el capacitor de arranque una vez que el motor alcanza su velocidad nominal.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (354, 15, 452, 'Compresores trifásicos y control de capacidad en sistemas de refrigeración', 'En esta lección, el instructor Mario explica en detalle el funcionamiento de los compresores trifásicos y su relación con los sistemas de control de capacidad. A lo largo del video se analizan los métodos de control en sistemas residenciales, comerciales e industriales, el uso de termostatos de una o varias etapas, los chillers con válvulas solenoides, y finalmente los motores de velocidad variable, ECM e Inverter.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (355, 15, 453, 'Diagnóstico de restricciones y fallas en el sistema de refrigeración', 'En esta lección, el instructor Mario enseña cómo detectar restricciones en un sistema de refrigeración utilizando nitrógeno y manómetros, así como a diagnosticar válvulas dañadas dentro del compresor mediante el procedimiento de pump down. Se explican los pasos prácticos que un técnico debe seguir en campo para garantizar que el sistema no presente bloqueos, fugas o fallas internas antes de hacer vacío o recargar refrigerante.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1132282258?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Diagnóstico de restricciones y fallas en el sistema de refrigeración\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 19, 15, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (356, 15, 453, 'Prácticas de laboratorio: calibración del manifold y uso del PT Chart', 'En esta lección, el instructor Mario guía a los estudiantes en las prácticas de laboratorio relacionadas con la calibración del manifold, la lectura del PT Chart y la identificación de refrigerantes mediante la relación entre presión y temperatura. También se revisan los componentes del ciclo de refrigeración, los tipos de motores y compresores, y las conexiones en Y y delta de los motores trifásicos. La sesión prepara a los alumnos para aplicar sus conocimientos teóricos en actividades prácticas de diagnóstico y medición.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1132282720?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Prácticas de laboratorio: calibración del manifold y uso del PT Chart\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 17, 36, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (357, 15, 453, 'Identificación de refrigerantes y calibración de manómetros en sistemas HVAC', 'En esta lección aprenderás a identificar correctamente los diferentes tipos de refrigerantes y detectar cuándo están mezclados. Además, el instructor explica cómo calibrar los manómetros antes de realizar una medición, utilizando la aplicación “Check Charge” para comparar presiones y temperaturas según el tipo de gas. Se destaca la importancia de la calibración a nivel del mar y cómo la presión atmosférica influye en las lecturas del sistema.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1132283039?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Identificación de refrigerantes y calibración de manómetros en sistemas HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 23, 28, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (358, 15, 454, 'Introducción a las conexiones eléctricas básicas y arranque de motores monofásicos', 'En esta primera lección, el instructor Mario introduce los fundamentos de la conexión eléctrica en motores utilizados en sistemas de refrigeración y aire acondicionado.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (359, 15, 454, 'Capacitores de arranque y marcha en motores monofásicos: teoría, conexión y diagnóstico práctico', 'En esta lección, el instructor Mario explica de forma detallada el funcionamiento y la conexión de los capacitores de arranque (start) y de marcha (run) utilizados en motores monofásicos de refrigeración.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (360, 15, 454, 'Reconexión de motores eléctricos, medición de amperaje y diagnóstico de fallas comunes', 'En esta tercera lección, el instructor Mario guía a los estudiantes a través de un bloque completamente práctico enfocado en la reconexión y verificación eléctrica de motores monofásicos.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (361, 15, 454, 'Motores de doble voltaje (Dual Voltage), rotación del sentido de giro y lectura de placa de características', 'En esta última lección, el instructor Mario explica el funcionamiento de los motores dual voltage y enseña a leer e interpretar la placa de características del motor, donde se especifican valores como voltaje, amperaje, modelo y tipo de conexión.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (362, 15, 451, 'Revisión final del circuito de arranque del compresor: diagnóstico integral y recomendaciones de mantenimiento', 'En esta última lección del módulo, el instructor Mario realiza una evaluación práctica completa del sistema eléctrico de arranque del compresor.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (363, 12, 455, 'Introducción a la Unidad 9 y Normas del EPA', 'En esta lección, el instructor introduce la Unidad 9 del libro, enfocada en la recuperación, reciclaje y reclamación de refrigerantes. También explica la importancia ambiental de estos procesos y repasa conceptos clave que aparecerán en el examen del EPA. El estudiante recibe una visión clara del propósito de la unidad, sus objetivos y la relación entre el manejo adecuado de refrigerantes y la protección del medio ambiente. Además, se mencionan problemas comunes con los exámenes, accesos bloqueados y recomendaciones técnicas importantes de seguridad.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1132555684?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Introducción a la Unidad 9 y Normas del EPA\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 22, 12, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (364, 12, 455, 'Rompimiento de la Capa de Ozono y Contaminación Atmosférica', 'En esta lección, el instructor explica cómo los refrigerantes afectan directamente la capa de ozono y el equilibrio climático del planeta. Se analiza la diferencia entre estratosfera y troposfera, los tipos de ozono (bueno y malo) y el impacto de los compuestos CFC, HCFC y HFC. Además, se mencionan los cambios ambientales en ciudades como Los Ángeles, la contaminación por smog y los esfuerzos del gobierno para reducir gases nocivos. El estudiante comprenderá cómo las acciones humanas y las políticas ambientales se relacionan con el trabajo técnico en HVAC.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1132557245?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Rompimiento de la Capa de Ozono y Contaminación Atmosférica\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 34, 47, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (365, 12, 455, 'Refrigerantes Alternativos y Certificaciones Industriales (RETA y Ammonia)', 'En esta lección, el instructor presenta los refrigerantes ecológicos y explica cómo la industria está migrando hacia opciones con menor impacto ambiental. Se analizan gases como el amoniaco (NH₃), el propano y otros hidrocarburos, junto con sus riesgos, ventajas y regulaciones.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (366, 12, 456, 'Fundamentos de los Refrigerantes y Clasificación General', 'En esta primera lección, el instructor introduce el tema central de los refrigerantes, explicando su papel en los sistemas de refrigeración y aire acondicionado. Se repasan los principios básicos del intercambio de calor, la función de evaporación y condensación, y cómo los diferentes tipos de refrigerantes permiten que estos procesos ocurran de manera controlada.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (367, 12, 456, 'Grupos de Refrigerantes: HCFC, HFC y Nuevas Generaciones (HFO)', 'En esta segunda lección, el instructor profundiza en las familias químicas de los refrigerantes que reemplazaron a los compuestos más dañinos de generaciones anteriores.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (368, 12, 456, 'Hidrocarburos, Aplicaciones Prácticas, Seguridad y Cierre de la Unidad 9', 'En esta tercera y última lección, el instructor aborda los hidrocarburos (HC) como una alternativa natural a los refrigerantes sintéticos. Explica sus propiedades, ventajas ecológicas y los riesgos de inflamabilidad que exigen un manejo responsable.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (369, 12, 457, 'Introducción a la Recuperación de Refrigerantes y Normativas EPA', 'En esta primera lección, el instructor Mario presenta el concepto de recuperación de refrigerantes, las razones ambientales y legales que justifican su correcta manipulación, y las normas del EPA que regulan el proceso. Se explican los riesgos de liberar gases al ambiente, la importancia de utilizar equipos certificados y las obligaciones del técnico HVAC frente a la legislación estadounidense.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1132561448?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Introducción a la Recuperación de Refrigerantes y Normativas EPA\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 33, 21, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (370, 12, 457, 'Procedimientos de Recuperación y Métodos Activo y Pasivo', 'En esta segunda parte, el instructor Mario profundiza en los métodos prácticos de recuperación de refrigerantes, diferenciando entre el método activo (con compresor) y el pasivo (por presión del sistema). Explica paso a paso cómo realizar el proceso con seguridad, el uso correcto del manifold y las mangueras, la verificación de presión, y las condiciones en que se debe detener o continuar la recuperación. También aborda las categorías de equipos, el almacenamiento del gas y los errores comunes que los técnicos deben evitar.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1132561887?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Procedimientos de Recuperación y Métodos Activo y Pasivo\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 33, 0, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (371, 12, 457, 'Reciclaje, Reclamación y Manejo Profesional de Refrigerantes', 'En esta tercera parte, el instructor Mario explica en profundidad los conceptos de reciclar y reclamar refrigerantes, detallando las diferencias, los equipos que se utilizan y las normas del EPA que regulan estas operaciones. Además, enseña cómo identificar refrigerantes contaminados, cómo etiquetar correctamente los tanques y cómo registrar los datos de recuperación y reciclaje para cumplir con los requisitos legales. La lección concluye con recomendaciones sobre ética laboral, responsabilidad ambiental y buenas prácticas del técnico certificado.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1132566321?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Reciclaje, Reclamación y Manejo Profesional de Refrigerantes\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 32, 56, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (372, 12, 458, 'Preparación y Conexión del Sistema de Recuperación', 'En esta primera lección, el instructor enseña cómo preparar y conectar correctamente un sistema de recuperación de refrigerante utilizando un manifold, mangueras, tanque y bomba de vacío.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (373, 12, 458, 'Procedimiento de Vacío, Báscula y Recuperación del Refrigerante', 'En esta lección, el instructor lleva a cabo el procedimiento práctico de vacío y recuperación del refrigerante, aplicando los conceptos de conexión explicados en la Lección 1.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (374, 12, 458, 'Verificación Final, Tipos de Refrigerante y Cierre del Proceso de Recuperación', 'En esta última lección, el instructor revisa y explica los procedimientos finales del proceso de recuperación, verificando presiones, peso total recuperado y condiciones del refrigerante.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (375, 12, 459, 'Chiller enfriado por aire: funcionamiento, sensores y control por etapas', 'En esta lección aprenderás cómo funciona un chiller enfriado por aire, comprendiendo la estructura interna del sistema, los sensores que lo controlan, el funcionamiento del compresor recíproco y la manera en que se regulan las etapas de carga mediante válvulas solenoides. El instructor explica cómo se monitorean presiones, temperaturas y señales eléctricas desde la tarjeta electrónica del chiller, permitiendo un control preciso del ciclo de refrigeración.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1133717198?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Chiller enfriado por aire: funcionamiento, sensores y control por etapas\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 18, 31, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (376, 12, 459, 'Chiller enfriado por agua: evaporador, condensador y mantenimiento interno', 'En esta lección, el instructor presenta un chiller de 400 toneladas enfriado por agua, explicando en detalle cómo circula el agua dentro del sistema, cómo se separan y protegen los componentes del condensador y del evaporador, y cómo se realiza el mantenimiento preventivo interno, incluyendo la limpieza de los tubos. Se analiza también la importancia de la purga de aire, los sensores de temperatura del agua y las válvulas de control que garantizan la eficiencia del ciclo térmico.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1133717339?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Chiller enfriado por agua: evaporador, condensador y mantenimiento interno\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 24, 53, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (377, 12, 459, 'Chillers de baja presión y compresores centrífugos: control, operación y seguridad', 'En esta lección, el instructor analiza los chillers de baja presión y explica las diferencias con los sistemas de alta presión vistos anteriormente. Se estudia el funcionamiento de los compresores centrífugos, su sistema de lubricación, los controles de etapas mediante válvulas deslizantes (plugas), y la interacción con el condensador y el evaporador.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (378, 12, 459, 'Operación y control electrónico de chillers: monitoreo, purgas y seguridad', 'En esta última parte del video, el instructor profundiza en los controles electrónicos y en la operación diaria de chillers de gran capacidad, incluyendo sistemas con monitoreo remoto. También se explican los límites de presión, los sistemas de purga de gases no condensables, la importancia del aceite como elemento de protección, y los criterios de seguridad en pruebas y mantenimiento.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (379, 12, 460, 'Fundamentos del EPA CORE: motivación, estructura del examen y ciclo de refrigeración', 'En esta primera lección, el instructor introduce a los estudiantes al examen de certificación EPA 608, explicando su estructura, propósito y la importancia de la preparación constante.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (380, 12, 460, 'Instrumentos del técnico EPA: uso de gauges, control de vacío y clasificación de refrigerantes', 'En esta lección, el instructor enseña cómo interpretar las lecturas de los instrumentos de servicio más utilizados en el área de refrigeración: manifold gauge, compound gauge, y vacuum gauge.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (381, 12, 460, 'Mezclas refrigerantes: azeotrópicos, zeotrópicos y carga por punto de burbuja y rocío', 'En esta lección, el instructor explica en profundidad cómo se clasifican los refrigerantes mezclados, un tema clave del examen EPA CORE y Tipo II.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (382, 12, 460, 'Regulaciones EPA: recuperación, reciclaje y manejo responsable de refrigerantes', 'En esta lección final, el instructor explica las regulaciones oficiales del EPA 608, abordando el uso, recuperación y reciclaje de refrigerantes de acuerdo con la normativa ambiental vigente en Estados Unidos.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (383, 17, 461, 'Introducción al uso de tubería, materiales y fundamentos del equipo oxiacetilénico', 'En esta primera lección, el instructor da la bienvenida al taller “Manos a la obra”, orientado al trabajo práctico con tubería y soldadura oxiacetilénica.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (384, 17, 461, 'Encendido, purgado y control seguro del equipo oxiacetilénico: reguladores, válvulas y flama', 'En esta segunda lección, el instructor lleva a los alumnos a la parte práctica del curso, donde aprenden a preparar y encender correctamente el equipo oxiacetilénico, aplicando los principios teóricos vistos en la Lección 1.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (385, 17, 461, 'Ajuste de flama, tipos de flama y fundamentos prácticos de soldadura y brazing', 'En esta tercera lección, el instructor se centra en la formación, ajuste y control de la flama oxiacetilénica, enseñando a los alumnos a identificar los tres tipos principales de flama: carburante, neutra y oxidante.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (386, 17, 461, 'Práctica de brazing: aplicación de calor, uso del flujo y apagado seguro del equipo oxiacetilénico', 'En esta cuarta y última lección, el instructor lleva a cabo la práctica completa de brazing, aplicando todo lo aprendido sobre ajuste de flama, control de temperatura y seguridad.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (387, 17, 462, 'Preparación, corte y limpieza de tubería de cobre: fundamentos para una soldadura efectiva', 'En esta primera lección, el instructor introduce el trabajo práctico de tubería, explicando paso a paso el uso del cortador de tubo, el proceso de limpieza interna y externa, y la importancia del desbarbado para evitar restricciones en el flujo del refrigerante.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (388, 17, 462, 'Soldadura, expansión y conexión de tuberías de aluminio y cobre en sistemas de refrigeración', 'En esta segunda lección, el instructor continúa con la parte práctica del trabajo de tubería, introduciendo los procedimientos de expansión y soldadura en aluminio, así como las precauciones en el manejo de presión con nitrógeno.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (389, 17, 463, 'Instalación práctica de tubing y piping en sistemas de refrigeración', 'En esta primera lección práctica, el instructor Mario guía paso a paso el proceso de trabajo con tubería de cobre (tubing) utilizada en los sistemas HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (390, 17, 464, 'Fundamentos del tubing y piping: materiales, seguridad y principios del brazing', 'En esta primera lección, el instructor introduce el mundo del tubing y piping aplicado a la refrigeración y climatización.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (391, 17, 464, 'Aplicación del flux, brazing, y uso de herramientas para flare y swaging', 'En esta segunda lección, el instructor continúa el módulo “Manos a la Obra” pasando de la teoría a la demostración práctica.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (392, 17, 464, 'Flare y Swaging: técnicas de unión, prácticas de taller y preparación para el armado del sistema', 'En esta tercera y última lección del módulo “Manos a la Obra”, el instructor se centra en las técnicas de flare y swaging, mostrando la aplicación práctica de los conceptos aprendidos en las sesiones anteriores.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (393, 17, 465, 'Introducción al trabajo de tuberías, seguridad, herramientas y preparación del área de práctica', 'En esta primera lección, el instructor presenta al grupo de estudiantes y explica el propósito de la práctica denominada “Tubing and Piping – Manos a la Obra”.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (394, 17, 465, 'Técnicas de soldadura, regulación de oxígeno y acetileno, y control de flama para unión de tuberías', 'En esta segunda lección, el instructor continúa con la práctica posterior al armado inicial de tuberías.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (395, 17, 465, 'Aplicación práctica del control de flama, revisión de uniones y conclusiones del módulo de Tubing & Piping', 'En esta tercera y última lección, el instructor retoma el trabajo iniciado con la flama y lleva a cabo una serie de prácticas finales de soldadura y ensamblaje de tuberías.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (396, 17, 466, 'Tubing and Piping: fundamentos, herramientas y técnicas prácticas en sistemas HVAC', 'En esta lección, el instructor realiza una revisión práctica sobre tuberías y conexiones (tubing and piping) aplicadas a sistemas de refrigeración y aire acondicionado.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (397, 19, 467, 'Fundamentos del Termostato y Controles por Temperatura', 'En esta lección, el instructor introduce los conceptos esenciales del termostato y su papel en los sistemas HVAC. El estudiante comprenderá cómo funcionan los controles de temperatura, de qué manera los switches responden al cambio térmico y por qué el termostato es la primera línea de defensa en calefacción y aire acondicionado. También se revisan principios de transferencia de calor, la importancia del ambiente interior y cómo se desencadenan las llamadas de enfriamiento o calefacción.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139004824?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Fundamentos del Termostato y Controles por Temperatura\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 33, 33, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (398, 19, 467, 'Operación del Termostato en Calefacción y Señales del Sistema HVAC', 'En esta lección, el estudiante profundiza en el funcionamiento del termostato aplicado al modo de calefacción. Se analiza cómo se desencadena la llamada de calor, cómo responden los switches de temperatura y qué papel juega el blower. Además, se introduce la lógica detrás del transformador, los motores del sistema y otros componentes esenciales que trabajan bajo señales del termostato. Esta lección prepara al estudiante para comprender el flujo eléctrico básico que activa y coordina el sistema HVAC.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139005648?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Operación del Termostato en Calefacción y Señales del Sistema HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 33, 0, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (399, 19, 467, 'Transformador, Controles Automáticos y Componentes del Sistema HVAC', 'En esta lección, el estudiante estudia en profundidad los componentes que trabajan con los 24 voltios del sistema HVAC: el transformador, los motores, los sensores y los controles automáticos. También se explican los diferentes tipos de switches, la función del blower motor, el meaning de los cables R, G, Y y W, y cómo se distribuyen las señales desde el termostato hacia los distintos elementos del equipo. Esta lección concluye con la explicación del ciclo de seguridad de la calefacción y el funcionamiento del drenaje, así como la importancia de los controles de nivel de agua.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139006148?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Transformador, Controles Automáticos y Componentes del Sistema HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 29, 19, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (400, 19, 468, 'Introducción a los Controles HVAC Basados en Temperatura', 'En esta lección se estudian los principales componentes de HVAC que reaccionan a cambios de temperatura. El instructor explica dispositivos como el fan controller, overload protector, defrost termination device, secuenciador y bainero. También introduce cómo estos elementos activan o protegen equipos de calefacción y refrigeración usando principios térmicos y mecánicos.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139007236?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Introducción a los Controles HVAC Basados en Temperatura\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 20, 19, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (401, 19, 468, 'Cálculos Eléctricos y Funcionamiento de Secuenciadores', 'En esta lección aprenderás a realizar cálculos fundamentales para determinar la capacidad y operación de calentadores eléctricos en sistemas HVAC. Se explica cómo convertir watts a BTUs, cómo calcular amperaje, cómo se dimensionan elementos calefactores y por qué se usan secuenciadores. Además, se contrasta el uso de calentadores eléctricos vs. de gas y se resalta la importancia de entender el comportamiento térmico para evitar sobrecargas en el sistema.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139008417?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Cálculos Eléctricos y Funcionamiento de Secuenciadores\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 28, 28, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (402, 19, 468, 'Pruebas Prácticas de Termocuplas y Termopilas', 'En esta lección se realizan pruebas prácticas con termocuplas, termopilas y otros dispositivos de seguridad utilizados en equipos de calefacción, como calentadores y hornos. El instructor muestra en tiempo real cómo medir milivoltios, cómo reacciona cada sensor ante el calor, cómo funcionan los sistemas de seguridad que dependen de flama, y cómo diagnosticar fallas comunes. También utiliza antorchas, multímetros y demostraciones visuales para reforzar el aprendizaje.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139008977?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Pruebas Prácticas de Termocuplas y Termopilas\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 8, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (403, 19, 468, 'Sistemas de Seguridad por Flama en HVAC', 'En esta lección se profundiza en cómo operan los sistemas de seguridad basados en flama y temperatura en equipos HVAC. El instructor explica el funcionamiento real de la termocupla, la termopila, el rod & tube, los discos bimetálicos y diferentes sensores térmicos utilizados para activar o detener la operación del equipo. También se revisa por qué estos dispositivos protegen al usuario evitando fugas de gas o sobrecalentamiento, y se muestran casos reales en los que el equipo no funcionará si cualquiera de estos elementos falla.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139009813?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Sistemas de Seguridad por Flama en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 28, 42, 0, 4, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (404, 19, 469, 'Sensores y Controles Automáticos en HVAC', 'En esta lección, el estudiante aprenderá los principios fundamentales de los controles automáticos utilizados en sistemas HVAC. Se explican los diferentes tipos de sensores de temperatura —incluyendo termopares, termopilas y termistores PTC y NTC— así como su función en el arranque, paro y protección de equipos. También se abordan componentes mecánicos como bimetales, diafragmas, bellows, snap disks y varilla-tubo, además de sensores de presión y transductores. El instructor utiliza la Unidad 13, hoja número 13, como base teórica y guía al estudiante para identificar estos componentes en campo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1137881937?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Sensores y Controles Automáticos en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 14, 22, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (405, 19, 470, 'Fundamentos de Componentes y Controles HVAC', 'En esta primera lección el estudiante se familiarizará con los controles esenciales utilizados en sistemas HVAC. El instructor explica cómo funcionan los componentes más comunes en base a temperatura, presión, expansión térmica y fluidos. Se estudian sensores, termopares, termopilas, snap discs, interruptores de presión y termostatos mecánicos, además de una introducción detallada a los termistores PTC y NTC. Esta lección establece los cimientos técnicos indispensables para entender el comportamiento de los equipos en campo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139010764?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Fundamentos de Componentes y Controles HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 30, 48, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (406, 19, 470, 'Controles Especializados y Aplicaciones Prácticas en HVAC', 'En esta lección se profundiza en controles avanzados utilizados en equipos HVAC, incluyendo termostatos digitales, termostatos mecánicos de fluidos, temporizadores, defrost timers, defrost termination switches, válvulas solenoides, controles neumáticos, y mecanismos de protección del compresor. Además, se introduce la participación del estudiante en la identificación práctica de los componentes, dando el puente natural entre teoría y práctica real de campo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139013794?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Controles Especializados y Aplicaciones Prácticas en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 30, 36, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (407, 19, 470, 'Aplicación Práctica y Casos Reales de Diagnóstico en HVAC', 'En esta lección el estudiante observa la ejecución práctica del instructor y los alumnos al manipular componentes reales, analizar motores, identificar velocidades, interpretar capacitores y relays, y comprender transformadores de control. También se discuten casos reales de campo, mantenimiento, errores comunes y costos asociados. Es una lección que vincula la teoría con la práctica completa, preparando al estudiante para escenarios profesionales.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139014444?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Aplicación Práctica y Casos Reales de Diagnóstico en HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 17, 49, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (408, 19, 471, 'Demostración Práctica del Control de Ventilador y Límites de Temperatura', 'En esta lección, el instructor explica de forma práctica cómo funcionan los controles de ventilador (Fan Control) y los interruptores de límite de temperatura (High Limit). A través de demostraciones en vivo, los estudiantes observan cómo el calor afecta el movimiento del disco bimetálico, cómo se mide continuidad en diferentes terminales y cómo se ajustan manualmente los límites de operación entre 100°F y 200°F. La lección establece una base sólida para comprender la relación entre temperatura, seguridad y funcionamiento del blower en los sistemas HVAC.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139014856?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Demostración Práctica del Control de Ventilador y Límites de Temperatura\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 18, 5, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (409, 19, 471, 'Prácticas de Laboratorio: Pruebas con Calor y Frío en Componentes HVAC', 'En esta lección, los estudiantes realizan prácticas de laboratorio aplicando calor, frío y pruebas de continuidad a distintos componentes HVAC como snap discs, termocuplas, terminadores de deshielo y sensores térmicos. El instructor guía paso a paso el uso adecuado del multímetro, la identificación de contactos normalmente abiertos/cerrados y la interpretación correcta del comportamiento térmico. Esta sesión es 100% práctica y está diseñada para que el estudiante adquiera habilidades reales de diagnóstico en campo.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1139015340?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Prácticas de Laboratorio: Pruebas con Calor y Frío en Componentes HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 23, 15, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (410, 13, 49, 'Examen: Curso de Calefacción', 'Este examen tiene como objetivo evaluar los conocimientos adquiridos en el curso Calefacción de AC Volt School. El estudiante será puesto a prueba en temas como fundamentos de sistemas de calefacción, zonificación, funcionamiento de compuertas, controles eléctricos, seguridad, gas, tipos de combustibles, control de temperatura y diagnóstico de fallas comunes. Ideal para reforzar el aprendizaje técnico aplicado en instalaciones residenciales y comerciales HVAC.', 2, '', '', 0, 0, 0, 30, 3, 0) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (411, 14, 31, 'Examen: Electricidad para Aire Acondicionado', 'Este examen evalúa los conocimientos adquiridos en el curso de Electricidad para Aire Acondicionado, incluyendo principios básicos de electricidad, magnetismo, circuitos en serie, ley de Ohm, y el uso de herramientas como el multímetro. Las preguntas están diseñadas para reforzar el análisis técnico y la aplicación práctica de conceptos fundamentales en sistemas HVAC.', 2, '', '', 0, 0, 0, 25, 11, 0) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (412, 19, 472, 'Controles Fundamentales del Sistema HVAC — Termostatos, Transformador, Sensores y Protecciones', 'En esta lección se introduce el estudio de los controles del sistema HVAC, comenzando con la explicación de qué es un control y cómo su función principal es abrir o cerrar un circuito.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (413, 19, 472, 'Humedad, Estados del Agua y Fundamentos del BTU — Calor Sensible y el Factor 1.08 en HVAC', 'En esta lección, el estudiante estudia en profundidad los conceptos fundamentales de humedad, vapor, calor sensible, calor latente y el BTU, que son esenciales para entender el comportamiento del aire dentro de un sistema HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (414, 19, 472, 'Cálculo de BTUs en Sistemas HVAC — CFM, Temperatura, 1.08 y Presión Estática', 'En esta lección, el estudiante aplica los conceptos aprendidos previamente sobre el 0.24 y el factor 1.08 para realizar cálculos reales de BTU/hora, utilizando las fórmulas fundamentales de HVAC:
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (415, 19, 473, 'Presostatos Mecánicos, Manifold y Fundamentos del Diagnóstico Inicial', 'En esta lección, el estudiante aprende el funcionamiento de los presostatos mecánicos de alta y baja presión, su relación con el manifold y su importancia como dispositivos de protección en sistemas HVAC. Se explica cómo interpretarlos durante un diagnóstico, por qué abren o cierran según la presión y cómo su comportamiento ayuda a identificar fallas en el sistema. También se introduce el orden correcto de diagnóstico, el cual será esencial para el resto del curso.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1141837822?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Presostatos Mecánicos, Manifold y Fundamentos del Diagnóstico Inicial\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 32, 30, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (416, 19, 473, 'Secuencia Completa de Diagnóstico, Controles del Sistema y Verificación de Voltajes', 'En esta lección, el estudiante aprende a seguir el procedimiento oficial de diagnóstico paso por paso, comenzando con la verificación del estado de los controles, la posición del termostato y la secuencia de pruebas recomendada por el instructor. Se estudian los switches de seguridad, cómo el equipo responde a cada paso del proceso, y cómo se verifican los voltajes en diferentes puntos del sistema HVAC. Esta lección concluye cuando el instructor llega al Paso 15 del procedimiento, donde se revisa el voltaje de línea de 120V entrando al relay.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1141838082?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Secuencia Completa de Diagnóstico, Controles del Sistema y Verificación de Voltajes\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 21, 28, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (417, 19, 473, 'Diagnóstico Avanzado, Voltajes de Línea, Relays y Secuencia de Seguridad del Sistema HVAC', 'En esta lección, el estudiante continúa con la secuencia de diagnóstico a partir del Paso 15, enfocándose en la verificación de voltaje de línea, el análisis del relay y la operación general del sistema HVAC bajo condiciones reales. El instructor explica cómo interpretar correctamente los 120V de entrada, cómo reaccionan los componentes eléctricos durante el ciclo, y cómo identificar fallas relacionadas con cableado, relays, motores o alimentación eléctrica. La lección culmina cuando finaliza la secuencia de diagnóstico y el instructor envía a los estudiantes a un descanso.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1141838463?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Diagnóstico Avanzado, Voltajes de Línea, Relays y Secuencia de Seguridad del Sistema HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 24, 38, 0, 3, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (418, 19, 474, 'Reguladores de presión de gas: funcionamiento, ajustes y fundamentos del sistema de combustión', 'En esta lección, el estudiante aprende los conceptos fundamentales sobre reguladores de presión de gas, incluyendo cómo funcionan, qué componentes los integran y cómo influyen directamente en el rendimiento de un sistema de combustión.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (419, 19, 474, 'Medición práctica del sistema de gas: fórmulas de conversión, differential pressure y clocking del medidor', 'En esta lección, el estudiante aprende el procedimiento profesional para determinar cuántos BTU reales está consumiendo un equipo, utilizando las fórmulas de conversión y el método conocido como clocking del medidor de gas.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (420, 19, 475, 'Introducción a los Componentes Fundamentales del Sistema de Control Eléctrico', 'En esta lección, el estudiante aprende a identificar los componentes esenciales que forman la base de un sistema de control eléctrico, particularmente en equipos HVAC y sistemas automatizados. Se estudian los presostatos, el manifold, los terminal blocks, los interruptores manuales y el transformador que suministra los 24 voltios necesarios para el circuito de control.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (421, 19, 475, 'Procedimiento de Diagnóstico Eléctrico: Termostato, Fusible, Transformador y Voltaje de Control', 'En esta lección, el estudiante aprende a realizar un diagnóstico secuencial del circuito de 24V, siguiendo un procedimiento organizado paso por paso. Se revisan las posiciones de los switches, la condición del termostato, el estado del transformador, la funcionalidad del fusible y la continuidad del cableado. El instructor explica cómo se debe medir adecuadamente el voltaje de control, cómo identificar la línea R y el común (C), y cómo verificar si el termostato está enviando señales correctas a los componentes del sistema HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (422, 19, 475, 'Diagnóstico de Voltaje de Línea, Pruebas de Relay, Contactores y Análisis de Embobinados', 'En esta lección, el estudiante aprende a trabajar con voltaje de línea (120 V), verificando la entrada hacia el relay y el funcionamiento interno de los componentes que operan con voltaje de potencia. Se analiza en detalle cómo funciona un relay, cómo probar su bobina y contactos, y cómo diferenciar entre contactos normalmente abiertos y normalmente cerrados. También se estudia el funcionamiento de un contactor, cómo identificar sus embobinados y cómo detectar una falla interna.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (423, 19, 476, 'Introducción a Contactores, Relés y Protecciones en el Sistema HVAC', 'En esta lección, el estudiante aprende los fundamentos eléctricos que gobiernan el funcionamiento de un sistema HVAC: el uso correcto del contactor, las diferencias con el relé, la función de la bobina, la importancia del voltaje de control, y cómo intervienen las protecciones en el circuito.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (424, 19, 476, 'Pruebas del Termostato, Jumper, Señales de Control y Anti-Short Protection', 'En esta lección, el estudiante entra a la parte práctica del sistema HVAC. Se inicia desde el Paso 17, donde se simula la demanda del termostato mediante jumpers para observar cómo reaccionan el blower, el compresor y el contactor. El instructor explica cómo interpretar el comportamiento del equipo según cada señal (Y, G, W) y cómo identificar problemas comunes cuando la unidad no responde.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (425, 19, 476, 'Medición de Amperaje y Sensores de Seguridad en el Sistema HVAC', 'En esta lección, el instructor guía al estudiante a través del proceso de medición de amperaje en distintos componentes del sistema HVAC durante calefacción y enfriamiento. Se profundiza en cómo identificar fallas usando mediciones reales, cómo interpretar el comportamiento del blower, y cómo funcionan los sensores de seguridad (alta, baja y térmicos) dentro del circuito.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (426, 12, 460, 'Examen: Química y Gestión de Refrigerantes y Aceites', 'Este examen está diseñado para evaluar los conocimientos adquiridos en el curso Química y Gestión de Refrigerantes y Aceites. Los estudiantes demostrarán su comprensión sobre la composición química de los refrigerantes, los tipos y propiedades de los aceites utilizados en sistemas HVAC, y las buenas prácticas de manejo de estos insumos. Además, se evalúa el conocimiento sobre normativas ambientales, clasificación de los gases y seguridad en su manipulación.', 2, '', '', 0, 0, 0, 25, 5, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (427, 17, 466, 'Examen: Tuberías y Sistema de Tuberías', 'Este examen evalúa el conocimiento práctico y teórico del estudiante sobre herramientas, técnicas de instalación, doblado, expansión, corte y soldadura de tuberías utilizadas en sistemas HVAC. Refuerza la identificación correcta de herramientas, los procesos de unión y sellado, así como la aplicación de regulaciones y buenas prácticas en el manejo de sistemas de tuberías de refrigeración y aire acondicionado. Está diseñado para validar que el estudiante pueda aplicar estos conceptos en escenarios reales del campo.', 2, '', '', 0, 0, 0, 25, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (428, 19, 477, 'Diagnóstico Inicial en Campo: Lectura de Condiciones, Herramientas y Mentalidad Profesional', 'En esta primera lección, el instructor utiliza una llamada de servicio real para enseñar la importancia del diagnóstico profesional. Explica por qué no se deben asumir fallas sin medir amperaje, revisar la placa del equipo o confirmar la carga del motor. Se destacan errores comunes del técnico inexperto que intenta cambiar piezas sin justificarlo.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (429, 19, 477, 'Diagnóstico de Capacitores y Motores PSC: Mediciones, Fallas Comunes y Procedimientos Correctos', 'En esta lección, el instructor profundiza en el funcionamiento de los motores PSC y los capacitores, explicando por qué fallan, cómo medirlos correctamente y cómo interpretar los valores obtenidos. También se aclaran errores frecuentes en el uso del multímetro, la diferencia entre pruebas energizadas y desenergizadas, y las implicaciones de un capacitor dual o separado.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (430, 19, 477, 'Pruebas Prácticas de Motores y Capacitores: Interpretación de Diagramas y Diagnóstico Completo', 'En esta lección, el instructor guía al estudiante a través de las pruebas prácticas más importantes para diagnosticar motores PSC, capacitores y bobinas internas. Se usa un diagrama real para explicar cómo se miden correctamente las bobinas RUN, START y COMMON, y cómo interpretar los valores de resistencia para determinar si el motor está en buen estado.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (431, 19, 478, 'Diagnóstico Inicial, Seguridad y Preparación del Sistema HVAC', 'En esta lección, el estudiante aprende la estructura correcta para iniciar cualquier diagnóstico HVAC: seguridad, inspección visual y verificación de señales iniciales. El instructor enseña la importancia de observar el equipo antes de medir, identificar fallas simples y evitar errores comunes de principiantes. Esta unidad prepara al estudiante para realizar diagnósticos más avanzados en las siguientes lecciones, estableciendo una metodología ordenada y profesional.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1143194397?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Diagnóstico Inicial, Seguridad y Preparación del Sistema HVAC\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 25, 57, 0, 1, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (432, 19, 478, 'Señales de Control, Verificación de Componentes y Diagnóstico Funcional Inicial', 'En esta lección, el estudiante aprende a interpretar correctamente las señales de control que gobiernan el funcionamiento del sistema HVAC. Se revisa cómo deben activarse los componentes, qué respuestas esperar del equipo y cómo identificar fallas tempranas cuando la señal existe pero el componente no responde. El instructor explica los pasos de verificación funcional antes de pasar al diagnóstico profundo, incluyendo conexiones, respuestas del motor, sensores, y comportamiento eléctrico básico. Esta unidad establece la base para comprender cómo “piensa” el sistema al recibir órdenes.', 0, '', '<div style=\"padding:56.25% 0 0 0;position:relative;\"><iframe src=\"https://player.vimeo.com/video/1143310398?badge=0&amp;autopause=0&amp;player_id=0&amp;app_id=58479\" frameborder=\"0\" allow=\"autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;\" title=\"Señales de Control, Verificación de Componentes y Diagnóstico Funcional Inicial\"></iframe></div><script src=\"https://player.vimeo.com/api/player.js\"></script>', 0, 16, 33, 0, 2, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (433, 19, 478, 'Capacitores, Motores, Conexiones Eléctricas y Lógica de Arranque del Sistema HVAC', 'Esta lección se adentra en la relación entre los capacitores, los motores y el arranque del sistema HVAC. El instructor explica cómo identificar el Common, Run y Start en un motor, así como la función precisa de cada terminal. Se detalla cómo fluye la capacitancia dentro del motor, por qué es necesaria para generar torque, y cómo detectar fallas típicas causadas por conexiones incorrectas o capacitores dañados.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (434, 19, 478, 'Seguridad Avanzada, Sensores, Monitoreo de Monóxido y Verificaciones Finales del Sistema HVAC', 'En esta lección, el estudiante aprende la parte más crítica del diagnóstico HVAC: la seguridad avanzada del sistema. El instructor explica el uso del detector de monóxido de carbono, el comportamiento de los sensores de seguridad, la revisión de quemadores, del intercambiador de calor, de la cámara de combustión, del blower y del drenaje.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (435, 19, 479, 'Fundamentos del Capacitor RUN y el Funcionamiento del Contactor Single-Pole en Sistemas HVAC', 'En esta primera lección, el estudiante comprende los principios esenciales para diagnosticar y conectar un compresor de aire acondicionado. El instructor explica el uso del capacitor RUN, la estructura del contactor single-pole, la función de los terminales L1, L2, T1 y T2, y el motivo por el que un lado del circuito queda “vivo” aun cuando el equipo está desenergizado.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (436, 19, 479, 'Comprensión del Capacitor START y su Integración en el Sistema de Arranque del Compresor HVAC', 'En esta segunda lección, el estudiante profundiza en el papel del capacitor START dentro del arranque de un compresor. El instructor explica cuándo es necesario utilizar un capacitor de arranque, cómo se diferencia del capacitor RUN y por qué ciertos compresores requieren un impulso inicial de torque.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (437, 19, 479, 'Integración del Potential Relay y Funcionamiento del Sistema de Arranque CSCR (Capacitor Start – Capacitor Run)', 'En esta tercera lección, el estudiante aprende en detalle cómo funciona el Potential Relay, un componente esencial para habilitar el capacitor START durante el arranque del compresor y desconectarlo en el momento exacto para evitar daños.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (438, 19, 480, 'Introducción al Sistema HVAC, Seguridad Eléctrica y Conceptos Base Antes del Diagnóstico', 'En esta primera lección, el instructor da inicio a la clase estableciendo el ambiente, dinámicas básicas y normas de seguridad para trabajar sobre equipos HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (439, 19, 480, 'Capacitor RUN, Terminales del Compresor y Pruebas Reales de Voltaje en Sistemas HVAC', 'En esta segunda lección, el estudiante entra por primera vez al análisis técnico del sistema eléctrico del compresor. El instructor explica el capacitor RUN, sus funciones y su conexión correcta en el circuito HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (440, 19, 480, 'Diagnóstico del Compresor: Lecturas Críticas, Identificación de Fallas y Funcionamiento del Enrollado START', 'En esta tercera lección, el instructor lleva al estudiante a un nivel más profundo de diagnóstico eléctrico, enfocándose en cómo identificar fallas reales en el compresor desde sus terminales C–R–S.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (441, 19, 480, 'El Potential Relay, los Voltajes Pick-Up y Drop-Off, y la Lógica Completa del Arranque CSCR', 'En esta cuarta lección, el estudiante comprende uno de los conceptos más importantes del sistema de arranque del compresor: el funcionamiento del Potential Relay y su relación con el capacitor START dentro del sistema CSCR (Capacitor Start – Capacitor Run).
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (442, 19, 480, 'Pruebas Finales en Vivo, Diagnóstico Avanzado y Cierre del Sistema HVAC', 'En esta quinta y última lección, el instructor realiza pruebas prácticas en tiempo real sobre el sistema HVAC para validar el funcionamiento correcto de todos los componentes estudiados previamente: capacitores, contactor, Potential Relay, devanados del compresor y cableado general.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (443, 19, 481, 'Fundamentos del Dew Point, Humedad Relativa y Psicrometría Aplicada (Preguntas 1–10 del módulo)', 'En esta primera lección, el estudiante profundiza en los principios esenciales de la psicrometría aplicados al diagnóstico HVAC. El instructor analiza conceptos clave como dew point, humedad relativa, temperatura dry bulb, wet bulb y la forma correcta de interpretar el estado del aire en diferentes escenarios.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (444, 19, 481, 'Entalpía, Contenido de Humedad y Transiciones Energéticas del Aire en HVAC', 'En esta segunda lección, el estudiante se adentra en el concepto de entalpía, una de las variables más importantes —y a la vez más ignoradas— en el análisis del aire acondicionado. El instructor explica qué representa realmente la entalpía, cómo se relaciona con el calor sensible y el calor latente, y por qué es indispensable para comprender el desempeño de una evaporadora.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (445, 19, 481, 'Relación entre Dry Bulb, Humedad Absoluta y Cálculo Conceptual de Estados del Aire (Condiciones de 70°F)', 'En esta tercera lección, el estudiante trabaja con la interpretación directa de condiciones psicrométricas específicas, iniciando con la frase: “Si tengo una condición de 70…”. El instructor utiliza este escenario para explicar cómo un estado del aire debe analizarse siempre considerando sus dos componentes esenciales: temperatura y humedad.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (446, 19, 481, 'Medición en Campo: Instrumentos, Condiciones Reales y Análisis Psicrométrico Aplicado', 'En esta cuarta lección, los estudiantes pasan de la teoría a la práctica. El instructor introduce el uso de instrumentos para medir condiciones reales del aire, guiando al grupo a trabajar fuera del aula para obtener lecturas de dry bulb, wet bulb, humedad, retorno, suministro y otras variables psicrométricas.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (447, 19, 481, 'Análisis de Condiciones del Aire en un Equipo en Operación y Continuación del Módulo de Preguntas (31 en adelante)', 'En esta quinta lección, el instructor retoma la explicación del comportamiento del equipo analizado en la lección anterior y profundiza en la interpretación de sus condiciones internas. Se revisan las mediciones tomadas, se explica el porqué de las lecturas obtenidas y cómo estas reflejan el funcionamiento real de una unidad HVAC bajo carga.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (448, 19, 481, 'Interpretación Avanzada de Preguntas Psicrométricas y Análisis de Condiciones del Aire (Preguntas 31–40)', 'En esta sexta lección, el instructor continúa con el módulo de preguntas avanzadas, profundizando en la lógica psicrométrica y en la interpretación de distintos escenarios del aire acondicionado. A partir de la pregunta número 31, el estudiante repasa cómo evaluar condiciones del aire, identificar variaciones entre retorno y suministro, y conectar estas condiciones con el desempeño de la evaporadora.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (449, 19, 481, 'Uso de Aplicaciones Digitales HVAC: Fieldpiece / Joblink y Lecturas Avanzadas de Condiciones del Aire', 'En esta séptima lección, el instructor introduce el uso de herramientas digitales para el diagnóstico profesional HVAC, específicamente la aplicación Joblink de Fieldpiece. El estudiante aprende cómo interpretar lecturas en tiempo real del retorno, suministro, entalpía, humedad absoluta, granos de humedad y otros parámetros críticos capturados por sensores electrónicos.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (450, 19, 481, 'Interpretación Final de Mediciones, Uso de Joblink y Conclusiones del Día', 'En esta última lección del día, el instructor concluye el análisis psicrométrico y las mediciones usando la aplicación Joblink de Fieldpiece. El estudiante observa cómo se integran todas las variables revisadas durante la clase —entalpía, humedad absoluta, granos de humedad, temperaturas de retorno y suministro— en un diagnóstico general del sistema.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (451, 19, 482, 'Introducción a los Fundamentos de Aire Acondicionado y el Proceso de Remoción de Humedad', 'En esta primera lección, el instructor introduce los conceptos fundamentales del aire acondicionado aplicados al proceso de confort humano. Se explica la función principal del sistema: remover calor sensible y calor latente, destacando la importancia de la humedad relativa en el ambiente interior.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (452, 19, 482, 'Cálculo de Granos de Humedad, Libras de Agua y Fundamentos de Carga Latente en HVAC', 'En esta segunda lección, el estudiante aprende a transformar el concepto de granos de humedad en cálculos reales de carga latente. El instructor desarrolla paso a paso el proceso para convertir granos a libras de agua por libra de aire seco, y cómo esa diferencia determina cuánta humedad debe remover un sistema HVAC.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (453, 19, 482, 'Aplicación Psicrométrica: Conversión a Libras de Agua, Flujo de Aire y Galones por Hora en Sistemas HVAC', 'En esta tercera lección, el instructor profundiza en el cálculo de la humedad total que un sistema HVAC debe remover, integrando la conversión de granos a libras de agua con el flujo de aire del equipo. El estudiante aprende cómo determinar cuánta agua se extrae por hora y cómo relacionar estos resultados con la capacidad real del sistema.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (454, 19, 482, 'Tipos de Compresores en HVAC: Recíproco, Scroll, Rotary y Consideraciones de Funcionamiento', 'En esta cuarta lección, el instructor introduce los principales tipos de compresores utilizados en sistemas de aire acondicionado y sus diferencias operativas. Se analizan el compresor recíproco, el scroll y el rotary, explicando sus mecanismos internos, sus ventajas y desventajas, y las aplicaciones más comunes para cada uno.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (455, 19, 482, 'Tipos de Condensadores, Flujo de Aire, Montaje y Condiciones de Instalación en Sistemas HVAC', 'En esta quinta lección, el instructor aborda los distintos tipos de condensadores utilizados en aire acondicionado, explicando su importancia en la transferencia de calor y cómo el flujo de aire afecta directamente la eficiencia del sistema. Se describen configuraciones como top-discharge, side-discharge, verticales y horizontales, así como sus ventajas y limitaciones.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (456, 19, 482, 'Eficiencia SEER, Capacidades del Condensador y Revestimientos Protectores para Ambientes Corrosivos', 'En esta sexta lección, el instructor profundiza en el concepto de eficiencia estacional SEER y su impacto en el rendimiento del aire acondicionado. Se explica cómo el diseño del condensador, el tamaño del serpentín y la velocidad del ventilador contribuyen al valor SEER y por qué los equipos de alta eficiencia requieren más área de transferencia de calor.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (457, 19, 482, 'Dispositivos de Expansión: Tipos, Funcionamiento y Control del Flujo de Refrigerante en Sistemas HVAC', 'En esta séptima lección, el instructor explica el funcionamiento de los dispositivos de expansión, componentes esenciales que regulan el flujo de refrigerante hacia el evaporador. Se describen los principales tipos utilizados en aire acondicionado: capilar, pistón (orificio fijo) y válvula de expansión termostática (TXV).
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (458, 19, 482, 'Aplicación Final del Ciclo de Refrigeración, Revisión General y Preparación para Prácticas HVAC', 'En esta última lección, el instructor cierra el contenido del módulo repasando los elementos fundamentales del ciclo de refrigeración y su integración en un sistema HVAC real. Se conectan todos los componentes estudiados previamente —compresor, condensador, dispositivos de expansión y evaporador— explicando cómo trabajan en conjunto para controlar temperatura, presión y humedad.
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (459, 15, 454, 'Examen: Electricidad para Aire Acondicionado', 'Este examen evalúa los conocimientos adquiridos en el curso de Electricidad para Aire Acondicionado, incluyendo principios básicos de electricidad, magnetismo, circuitos en serie, ley de Ohm, y el uso de herramientas como el multímetro. Las preguntas están diseñadas para reforzar el análisis técnico y la aplicación práctica de conceptos fundamentales en sistemas HVAC.', 2, '', '', 0, 0, 0, 25, 5, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (460, 19, 482, 'Examen: Controles Automáticos', 'Este examen evalúa los conocimientos adquiridos sobre los principios y componentes de los controles automáticos aplicados a sistemas HVAC. Se refuerzan temas clave como el funcionamiento de termostatos, transformadores, anticipadores de calor, sub-bases, códigos de instalación y ubicación correcta de componentes. También se tocan elementos de seguridad como el snap disc, el termistor y se relacionan con la física del calor y la humedad. Ideal para comprobar que el estudiante puede aplicar estos conceptos tanto en teoría como en campo.', 2, '', '', 0, 0, 0, 25, 9, 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_lessons (old_id, old_course_id, old_section_id, title, description, lesson_type, video_filename, html_content, duration_hours, duration_minutes, duration_seconds, quiz_question_count, sort_order, status) VALUES (461, 20, 483, 'Bombas de Calor (Heat Pumps): Fundamentos, Ciclo Reversible y Operación de la Válvula de 4 Vías.', '🛠️ En esta lección, el instructor desglosa el funcionamiento de las Air Source Heat Pumps (bombas de calor enfriadas por aire), explicando por qué técnicamente son sistemas de refrigeración que tienen la capacidad única de bombear calor en dos direcciones: tanto hacia adentro como hacia afuera de una estructura
