INSERT INTO acvolt_answers (old_id, old_question_id, answer_text, status) VALUES (425, 107, 'Porque primero se debe conocer la resistencia total para calcular el consumo real', 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_answers (old_id, old_question_id, answer_text, status) VALUES (426, 107, 'Porque los vatios dependen solo del voltaje', 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_answers (old_id, old_question_id, answer_text, status) VALUES (427, 107, 'Porque los vatios de cada componente son siempre iguales', 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_answers (old_id, old_question_id, answer_text, status) VALUES (428, 107, 'Porque no es necesario calcular la potencia en un circuito paralelo', 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_answers (old_id, old_question_id, answer_text, status) VALUES (429, 108, 'En serie, las resistencias se suman; en paralelo, la resistencia total es menor que la menor resistencia del circuito', 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_answers (old_id, old_question_id, answer_text, status) VALUES (430, 108, 'En serie, las resistencias se dividen; en paralelo, se suman', 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_answers (old_id, old_question_id, answer_text, status) VALUES (431, 108, 'En paralelo, el voltaje se divide; en serie, es el mismo en todos los elementos', 1) ON CONFLICT (old_id) DO NOTHING;
INSERT INTO acvolt_answers (old_id, old_question_id, answer_text, status) VALUES (432, 108, 'No hay ninguna diferencia en cómo se comportan las resistencias', 1) ON CONFLICT (old_id) DO NOTHING;
